import { randomUUID } from 'crypto';
import { users } from '../storage/db.js';
import { hashPassword } from '../middleware/auth.js';

export async function ensureBootstrapAdmin() {
  const adminEmail = String(process.env.ADMIN_EMAIL || '')
    .trim()
    .toLowerCase();
  const adminPassword = String(process.env.ADMIN_PASSWORD || '').trim();
  const adminName = String(process.env.ADMIN_NAME || 'Administrador Recrutaria').trim();

  if (!adminEmail || !adminPassword) {
    console.warn(
      '[admin] ADMIN_EMAIL/ADMIN_PASSWORD não configurados. Bootstrap de admin ignorado.'
    );
    return;
  }

  const existing = (await users.findByEmail(adminEmail)) as any;
  if (existing) {
    if (existing.role !== 'admin') {
      throw new Error(
        `[admin] Usuário ${adminEmail} existe com role ${existing.role}. Não é possível promover automaticamente.`
      );
    }
    console.log(`[admin] Conta admin já existente: ${adminEmail}`);
    return;
  }

  const id = randomUUID();
  const passwordHash = await hashPassword(adminPassword);
  await users.create(id, adminEmail, passwordHash, 'admin', adminName || null);
  await users.verify(id);
  console.log(`[admin] Conta admin criada: ${adminEmail}`);
}

/**
 * CV Analysis — uses the smart AI provider (free first, paid fallback)
 * Includes caching to avoid redundant API calls.
 */

import { smartAI } from './provider.js';
import { aiCache } from './cache.js';
import crypto from 'crypto';

export interface CVAnalysisResult {
  score: number;
  strengths: string[];
  weaknesses: string[];
  suggestions: string[];
  reasoning?: string;
}

export interface AnalysisError {
  code: string;
  message: string;
}

export interface SafeResult {
  data: CVAnalysisResult | null;
  error: AnalysisError | null;
}

const FALLBACK: CVAnalysisResult = {
  score: 50,
  strengths: ['Tente novamente mais tarde.'],
  weaknesses: ['Serviço sobrecarregado.'],
  suggestions: ['Aguarde e tente novamente.'],
  reasoning: 'Análise indisponível no momento.',
};

/**
 * Generate cache key for CV analysis.
 * FIX: Uses SHA256 of the FULL CV text to avoid collision.
 * Previously used first 300 chars with MD5, causing two different CVs
 * with the same name/header to collide.
 */
function getCacheKey(cvText: string): string {
  return `cv_${crypto.createHash('sha256').update(cvText.trim()).digest('hex').substring(0, 24)}`;
}

export async function analyzeCVSafe(cvText: string): Promise<SafeResult> {
  if (!cvText || cvText.trim().length < 100) {
    return {
      data: null,
      error: { code: 'INVALID_INPUT', message: 'Currículo muito curto (mín. 100 caracteres)' },
    };
  }

  // Check cache first
  const cacheKey = getCacheKey(cvText);
  const cached = aiCache.get(cacheKey);
  if (cached) {
    console.log('[cv-analysis] 📦 Cache hit');
    return { data: cached as CVAnalysisResult, error: null };
  }

  try {
    const systemPrompt = `Analise este currículo de um candidato brasileiro e retorne APENAS JSON válido.`;
    const userContent = `Currículo:
${cvText.substring(0, 10000)}

Retorne JSON com:
- score: número inteiro 0-100 baseado nos padrões do mercado brasileiro
- strengths: array de 3-5 pontos fortes
- weaknesses: array de 3-5 pontos fracos ou áreas de melhoria
- suggestions: array de 3-5 sugestões específicas e acionáveis para melhorar o CV
- reasoning: resumo em 1-2 parágrafos em português`;

    const result = await smartAI('analyze', systemPrompt, userContent, true);
    const data = JSON.parse(result) as CVAnalysisResult;

    // Validate structure
    if (!data.score || !Array.isArray(data.strengths)) {
      throw new Error('Estrutura de resposta inválida');
    }

    // Clamp score to valid range (AI may return out-of-bounds values)
    data.score = Math.min(100, Math.max(0, Math.round(data.score)));

    // Cache for 7 days
    aiCache.set(cacheKey, data, 7 * 24 * 60 * 60 * 1000);

    return { data, error: null };
  } catch (err: any) {
    console.error('[cv-analysis] Error:', err.message);
    return {
      data: FALLBACK,
      error: { code: 'SERVICE_ERROR', message: err.message || 'Erro na análise' },
    };
  }
}

/**
 * AI Cache — caches AI responses to avoid redundant API calls
 *
 * Strategy:
 *   - Hash of (cvText snippet + jobRequirements) → cached result
 *   - TTL: 7 days for CV analysis, 30 days for job matching
 *   - Redis-compatible structure (for future scaling)
 */

import crypto from 'crypto';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const CACHE_DIR = path.join(__dirname, '..', '.ai-cache');

// Ensure cache directory exists
if (!fs.existsSync(CACHE_DIR)) {
  fs.mkdirSync(CACHE_DIR, { recursive: true });
}

interface CacheEntry<T> {
  hash: string;
  result: T;
  createdAt: number;
  ttl: number; // milliseconds
  hits: number;
}

class AICache {
  private maxEntries: number;
  private defaultTTL: number;

  constructor(maxEntries = 1000, defaultTTL = 7 * 24 * 60 * 60 * 1000) {
    this.maxEntries = maxEntries;
    this.defaultTTL = defaultTTL;
  }

  private hash(input: string): string {
    return crypto.createHash('md5').update(input).digest('hex');
  }

  private getCacheFile(key: string): string {
    return path.join(CACHE_DIR, `${key}.json`);
  }

  get<T>(key: string): T | null {
    try {
      const file = this.getCacheFile(key);
      if (!fs.existsSync(file)) return null;

      const raw = fs.readFileSync(file, 'utf-8');
      const entry: CacheEntry<T> = JSON.parse(raw);

      // Check TTL
      if (Date.now() - entry.createdAt > entry.ttl) {
        fs.unlinkSync(file);
        return null;
      }

      entry.hits++;
      fs.writeFileSync(file, JSON.stringify(entry));
      return entry.result;
    } catch {
      return null;
    }
  }

  set<T>(key: string, result: T, ttl?: number): void {
    try {
      // Evict old entries if over limit
      const files = fs.readdirSync(CACHE_DIR).filter((f) => f.endsWith('.json'));
      if (files.length >= this.maxEntries) {
        // Remove oldest entries
        const entries = files.map((f) => ({
          file: f,
          mtime: fs.statSync(path.join(CACHE_DIR, f)).mtime.getTime(),
        }));
        entries.sort((a, b) => a.mtime - b.mtime);

        const toDelete = entries.slice(0, Math.floor(this.maxEntries * 0.2));
        for (const e of toDelete) {
          fs.unlinkSync(path.join(CACHE_DIR, e.file));
        }
      }

      const entry: CacheEntry<T> = {
        hash: key,
        result,
        createdAt: Date.now(),
        ttl: ttl || this.defaultTTL,
        hits: 0,
      };

      fs.writeFileSync(this.getCacheFile(key), JSON.stringify(entry));
    } catch {
      // Silently fail — cache is non-critical
    }
  }

  clear(): void {
    try {
      const files = fs.readdirSync(CACHE_DIR).filter((f) => f.endsWith('.json'));
      for (const f of files) {
        fs.unlinkSync(path.join(CACHE_DIR, f));
      }
    } catch {
      /* ignore */
    }
  }

  stats(): { entries: number; hitRate: number } {
    try {
      const files = fs.readdirSync(CACHE_DIR).filter((f) => f.endsWith('.json'));
      let totalHits = 0;
      let validEntries = 0;

      for (const f of files) {
        const raw = fs.readFileSync(path.join(CACHE_DIR, f), 'utf-8');
        const entry: CacheEntry<any> = JSON.parse(raw);
        totalHits += entry.hits;
        if (Date.now() - entry.createdAt <= entry.ttl) {
          validEntries++;
        }
      }

      return {
        entries: validEntries,
        hitRate: files.length > 0 ? totalHits / files.length : 0,
      };
    } catch {
      return { entries: 0, hitRate: 0 };
    }
  }
}

export const aiCache = new AICache(1000, 7 * 24 * 60 * 60 * 1000);

/**
 * Generate cache key for CV analysis.
 * Uses first 500 chars of CV + job requirements hash.
 */
export function cvAnalysisCacheKey(cvText: string, jobTitle: string, requirements: string): string {
  const cvSnippet = cvText.substring(0, 500).trim();
  const jobHash = crypto
    .createHash('md5')
    .update(`${jobTitle}:${requirements}`)
    .digest('hex')
    .substring(0, 8);
  const cvHash = crypto.createHash('md5').update(cvSnippet).digest('hex').substring(0, 8);
  return `cv_${cvHash}_${jobHash}`;
}

/**
 * Generate cache key for bulk analysis batch.
 */
export function bulkAnalysisCacheKey(
  jobTitle: string,
  requirements: string,
  candidateCount: number
): string {
  const jobHash = crypto
    .createHash('md5')
    .update(`${jobTitle}:${requirements}`)
    .digest('hex')
    .substring(0, 8);
  return `bulk_${jobHash}_${candidateCount}`;
}

/**
 * AI Provider Router — tries free models first, falls back to paid
 *
 * Priority:
 *   1. OpenRouter free models (zero cost)
 *   2. Gemini via @google/genai (free tier: 15 RPM)
 *   3. OpenRouter paid models (paid)
 *   4. OpenAI direct (paid, last resort)
 *
 * Cost optimization strategies:
 *   - Cache prompts with ETag-like hashing
 *   - Use smaller models for simple tasks (matching, summary)
 *   - Use larger models only for complex analysis
 *   - Batch multiple requests in single calls when possible
 */

import fetch from 'node-fetch';

const OPENROUTER_KEY = process.env.OPENROUTER_API_KEY || '';
const GEMINI_KEY = process.env.GEMINI_API_KEY || '';
const OPENAI_KEY = process.env.OPENAI_API_KEY || '';

const OPENROUTER_BASE = 'https://openrouter.ai/api/v1/chat/completions';
const OPENAI_BASE = 'https://api.openai.com/v1/chat/completions';

// ── Free models on OpenRouter ──────────────────────────────────
const FREE_MODELS = {
  analyze: 'google/gemini-2.0-flash-exp:free', // CV analysis
  transcribe: 'meta-llama/llama-3.3-70b-instruct:free', // audio summary
  match: 'qwen/qwen-2.5-72b-instruct:free', // candidate-job matching
  questions: 'google/gemini-2.0-flash-exp:free', // pre-screening questions
  summarize: 'google/gemini-2.0-flash-exp:free', // candidate summary
};

// AI call timeout in milliseconds
const AI_TIMEOUT_MS = 30_000;

// ── Paid fallback models ───────────────────────────────────────
const PAID_MODELS = {
  analyze: 'anthropic/claude-sonnet-4-20250514',
  transcribe: 'openai/gpt-4o',
  match: 'openai/gpt-4o-mini',
  questions: 'openai/gpt-4o-mini',
  summarize: 'openai/gpt-4o-mini',
};

interface AIResponse {
  text: string;
  model: string;
  tokensUsed?: number;
}

/**
 * Calls OpenRouter with a model.
 */
async function callOpenRouter(
  model: string,
  messages: Array<{ role: string; content: string }>,
  jsonMode: boolean = false
): Promise<AIResponse | null> {
  if (!OPENROUTER_KEY) return null;

  try {
    const res = await fetch(OPENROUTER_BASE, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${OPENROUTER_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://recruta.ai',
        'X-Title': 'Recruta.AI',
      },
      body: JSON.stringify({
        model,
        messages,
        response_format: jsonMode ? { type: 'json_object' } : undefined,
        max_tokens: 2000,
        temperature: 0.3, // Lower temperature for consistent results
      }),
      signal: AbortSignal.timeout(AI_TIMEOUT_MS),
    });

    if (!res.ok) {
      const err = await res.text();
      console.warn(`[openrouter] ${model} failed: ${res.status} ${err.substring(0, 200)}`);
      return null;
    }

    const data: any = await res.json();
    const content = data.choices?.[0]?.message?.content;
    if (!content) return null;

    return {
      text: content,
      model,
      tokensUsed: data.usage?.total_tokens,
    };
  } catch (err: any) {
    console.warn(`[openrouter] ${model} error:`, err.message);
    return null;
  }
}

/**
 * Calls Gemini via Google AI API
 */
async function callGemini(
  systemPrompt: string,
  userContent: string,
  jsonMode: boolean = false
): Promise<AIResponse | null> {
  if (!GEMINI_KEY) return null;

  try {
    const { GoogleGenAI } = await import('@google/genai');
    const ai = new GoogleGenAI({ apiKey: GEMINI_KEY });

    const response = await Promise.race([
      ai.models.generateContent({
        model: 'gemini-2.0-flash',
        contents: `${systemPrompt}\n\n${userContent}`,
        config: jsonMode
          ? {
              responseMimeType: 'application/json',
            }
          : undefined,
      }),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error('Gemini timeout')), AI_TIMEOUT_MS)
      ),
    ]);

    if (!response.text) return null;
    return { text: response.text, model: 'gemini-2.0-flash' };
  } catch (err: any) {
    console.warn('[gemini] Error:', err.message);
    return null;
  }
}

/**
 * Calls OpenAI directly (most expensive, last resort)
 */
async function callOpenAI(
  model: string,
  messages: Array<{ role: string; content: string }>,
  jsonMode: boolean = false
): Promise<AIResponse | null> {
  if (!OPENAI_KEY) return null;

  try {
    const res = await fetch(OPENAI_BASE, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${OPENAI_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model,
        messages,
        response_format: jsonMode ? { type: 'json_object' } : undefined,
        max_tokens: 2000,
        temperature: 0.3,
      }),
      signal: AbortSignal.timeout(AI_TIMEOUT_MS),
    });

    if (!res.ok) return null;
    const data: any = await res.json();
    const content = data.choices?.[0]?.message?.content;
    if (!content) return null;

    return {
      text: content,
      model,
      tokensUsed: data.usage?.total_tokens,
    };
  } catch {
    return null;
  }
}

/**
 * Smart AI call — tries free first, falls back through tiers.
 * Logs which tier was used for cost tracking.
 */
export async function smartAI(
  task: keyof typeof FREE_MODELS,
  systemPrompt: string,
  userContent: string,
  jsonMode: boolean = false
): Promise<string> {
  const messages = [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent },
  ];

  // Tier 1: OpenRouter free model (zero cost)
  const freeResult = await callOpenRouter(FREE_MODELS[task], messages, jsonMode);
  if (freeResult) {
    console.log(`[ai] ✅ ${task} via OpenRouter FREE (${FREE_MODELS[task]})`);
    return freeResult.text;
  }

  // Tier 2: Gemini (free tier, 15 RPM)
  const geminiResult = await callGemini(systemPrompt, userContent, jsonMode);
  if (geminiResult) {
    console.log(`[ai] ✅ ${task} via Gemini FREE`);
    return geminiResult.text;
  }

  // Tier 3: OpenRouter paid (low cost)
  const paidResult = await callOpenRouter(PAID_MODELS[task], messages, jsonMode);
  if (paidResult) {
    console.warn(
      `[ai] ⚠️  ${task} via OpenRouter PAID (${PAID_MODELS[task]}) — ${paidResult.tokensUsed || '?'} tokens`
    );
    return paidResult.text;
  }

  // Tier 4: OpenAI direct (highest cost)
  const openaiResult = await callOpenAI(PAID_MODELS[task], messages, jsonMode);
  if (openaiResult) {
    console.warn(
      `[ai] ⚠️  ${task} via OpenAI PAID (${PAID_MODELS[task]}) — ${openaiResult.tokensUsed || '?'} tokens`
    );
    return openaiResult.text;
  }

  throw new Error('Todos os provedores de IA falharam. Verifique as chaves de API.');
}

/**
 * Get usage statistics for cost tracking.
 */
export async function getProviderStatus(): Promise<{
  freeModelsAvailable: string[];
  paidModelsFallback: string[];
  providers: { openrouter: boolean; gemini: boolean; openai: boolean };
}> {
  return {
    freeModelsAvailable: Object.keys(FREE_MODELS),
    paidModelsFallback: Object.keys(PAID_MODELS),
    providers: {
      openrouter: !!OPENROUTER_KEY,
      gemini: !!GEMINI_KEY,
      openai: !!OPENAI_KEY,
    },
  };
}

/**
 * Conversation Flow Orchestrator V3
 * Deterministic triage flow:
 * 1) Invite
 * 2) Explicit accept/decline
 * 3) Structured questions
 * 4) Final AI analysis (no random score)
 */

import { wa, dual } from '../storage/db.js';
import { sendTextMessage, sendTemplate, downloadMediaWithMeta } from '../whatsapp/client.js';
import { TEMPLATES, TEXT_MESSAGES } from '../whatsapp/templates.js';
import { transcribeAudio } from '../ai/transcribe.js';
import { analyzeCandidate, type CandidateAnalysis } from '../ai/analyze.js';
import { getAIControl, type AIControlSettings } from '../admin/ai-control.js';
import { generateQuestions, type GeneratedQuestion } from './questions.js';
import { encodeSessionAnalysis } from './summary.js';
import {
  buildStructuredQuestions,
  computeCompetencyScores,
  evaluateKnockoutReply,
  normalizeJobRequirements,
  type StructuredSessionQuestion,
} from './method.js';
import {
  isExplicitAcceptIntent,
  isExplicitDeclineIntent,
  isHumanHandoffIntent,
  isTextFallbackIntent,
  looksLikePromptInjection,
  sanitizeForModelInput,
} from './intents.js';

function uid(): string {
  return `${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

type SessionQuestion = {
  text: string;
  category: string;
  questionType: StructuredSessionQuestion['type'] | 'legacy';
  requirementId?: string;
  requirementText?: string;
  weight?: number;
};
type SessionQuestionType = SessionQuestion['questionType'];

function buildJobContext(job: any): string {
  const description = String(job?.description || '');
  const requirements = Array.isArray(job?.requirements)
    ? job.requirements
        .map((r: any) => (typeof r === 'string' ? r : String(r?.text || '')))
        .filter((r: string) => r.trim().length > 0)
    : [];

  if (requirements.length === 0) return description;
  return `${description}\n\nRequisitos-chave:\n- ${requirements.join('\n- ')}`;
}

function safeQuestions(input: unknown): SessionQuestion[] {
  if (!Array.isArray(input)) return [];
  return input
    .filter(
      (
        q
      ): q is {
        text?: unknown;
        category?: unknown;
        type?: unknown;
        questionType?: unknown;
        requirementId?: unknown;
        requirementText?: unknown;
        weight?: unknown;
      } => !!q && typeof q === 'object'
    )
    .map((q) => {
      const questionType: SessionQuestionType =
        q.questionType === 'knockout' || q.type === 'knockout'
          ? 'knockout'
          : q.questionType === 'bars' || q.type === 'bars'
            ? 'bars'
            : 'legacy';
      return {
        text: String(q.text || '').trim(),
        category: String(q.category || 'experience'),
        questionType,
        requirementId: typeof q.requirementId === 'string' ? q.requirementId : undefined,
        requirementText: typeof q.requirementText === 'string' ? q.requirementText : undefined,
        weight: Number.isFinite(Number(q.weight))
          ? Math.max(1, Math.min(5, Math.round(Number(q.weight))))
          : undefined,
      };
    })
    .filter((q) => q.text.length > 0);
}

async function buildSessionQuestionsForJob(
  job: { title?: string; description?: string; requirements?: unknown } | null
): Promise<SessionQuestion[]> {
  const jobTitle = String(job?.title || 'Vaga');
  const requirements = normalizeJobRequirements(job?.requirements);
  const structured = buildStructuredQuestions(jobTitle, requirements, {
    maxBarsQuestions: 4,
    maxKnockoutQuestions: 4,
  });
  if (structured.length > 0) {
    return structured.map((q) => ({
      text: q.text,
      category: q.category,
      questionType: q.type as SessionQuestionType,
      requirementId: q.requirementId,
      requirementText: q.requirementText,
      weight: q.weight,
    }));
  }

  const generated = await generateQuestions(jobTitle, buildJobContext(job), 4);
  return generated.map((q: GeneratedQuestion) => ({
    text: q.text,
    category: q.category,
    questionType: 'legacy',
  }));
}

async function ensureSessionQuestions(
  session: any,
  job: { title?: string; description?: string; requirements?: unknown } | null
): Promise<SessionQuestion[]> {
  const existing = safeQuestions(session?.questions);
  if (existing.length > 0) return existing;

  const normalized = await buildSessionQuestionsForJob(job);
  await wa.updateSessionQuestions(JSON.stringify(normalized), session.id);
  return normalized;
}

type AnsweredQuestion = {
  question: string;
  transcription: string;
  questionType: SessionQuestion['questionType'];
  requirementId?: string;
  requirementText?: string;
  weight?: number;
  category: string;
};

function extractAnsweredQuestions(
  questions: SessionQuestion[],
  responses: unknown
): AnsweredQuestion[] {
  if (!Array.isArray(responses)) return [];

  return responses
    .filter((response: any) => response?.system !== 'deep_dive_requested' && !response?.system)
    .map((response: any, idx: number) => {
      const fallbackIdx = Number.isFinite(response?.questionIdx)
        ? Number(response.questionIdx)
        : idx;
      const questionMeta = questions?.[fallbackIdx];
      const question = String(response?.question || questionMeta?.text || `Pergunta ${idx + 1}`);
      const transcription = sanitizeForModelInput(
        String(response?.text || response?.transcription || '').trim()
      );
      const questionType: SessionQuestionType =
        response?.questionType === 'knockout' || questionMeta?.questionType === 'knockout'
          ? 'knockout'
          : response?.questionType === 'bars' || questionMeta?.questionType === 'bars'
            ? 'bars'
            : 'legacy';

      return {
        question,
        transcription,
        questionType,
        requirementId:
          typeof response?.requirementId === 'string'
            ? response.requirementId
            : questionMeta?.requirementId,
        requirementText:
          typeof response?.requirementText === 'string'
            ? response.requirementText
            : questionMeta?.requirementText,
        weight: Number.isFinite(Number(response?.weight))
          ? Math.round(Number(response.weight))
          : questionMeta?.weight,
        category: String(response?.category || questionMeta?.category || 'experience'),
      };
    })
    .filter((qa) => qa.transcription.length > 0);
}

function fallbackAnalysis(qaCount: number): CandidateAnalysis {
  const baseScore = 50 + Math.min(40, qaCount * 10);
  return {
    matchScore: Math.max(0, Math.min(100, baseScore)),
    summary:
      'Triagem concluída com análise parcial por fallback. Recomendamos validação manual antes da próxima etapa.',
    strengths: ['Completou a triagem em áudio'],
    concerns: ['Análise automática indisponível no momento'],
    recommendation: 'mais_info',
    questionScores: Array.from({ length: qaCount }, () => 60),
    competencyScores: [],
  };
}

function canUseTextFallback(userMessage: string, control: AIControlSettings): boolean {
  return control.textFallbackEnabled && isTextFallbackIntent(userMessage);
}

function hasDeepDiveMarker(responses: unknown, questionIdx: number): boolean {
  if (!Array.isArray(responses)) return false;
  return responses.some(
    (r: any) =>
      r &&
      typeof r === 'object' &&
      Number(r.questionIdx) === questionIdx &&
      r.system === 'deep_dive_requested'
  );
}

function shouldAskDeepDive(
  question: SessionQuestion | undefined,
  message: string,
  control: AIControlSettings
): boolean {
  if (!control.deepDiveEnabled) return false;
  const content = String(message || '').trim();
  if (!content) return false;

  const normalized = content
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase();
  const wordCount = normalized.split(/\s+/).filter(Boolean).length;
  const hasNumberSignal = /\d/.test(normalized);
  const mentionsResultSignal =
    /(resultado|impacto|entrega|meta|aumentou|reduziu|percentual|prazo|kpi)/i.test(normalized);
  const category = String(question?.category || 'experience').toLowerCase();
  const expectsEvidence = ['experience', 'technical', 'behavioral'].includes(category);

  if (!expectsEvidence) return false;
  if (wordCount < 20) return true;
  if (!hasNumberSignal && !mentionsResultSignal && wordCount < 40) return true;
  return false;
}

function buildDeepDivePrompt(question: SessionQuestion | undefined): string {
  const base = String(question?.text || 'sua resposta anterior');
  return `Obrigado. Para uma avaliação justa, preciso de um pouco mais de contexto sobre "${base}".\n\nExplique no formato *Situação -> Ação -> Resultado*, incluindo um exemplo concreto e, se possível, um número de impacto.`;
}

async function finalizeSession(
  session: any,
  job: any,
  questions: SessionQuestion[],
  control: AIControlSettings
): Promise<{ nextState: 'completed'; recruiterSummary: string }> {
  const refreshedSession = (await wa.getSession(session.id)) as any;
  const answered = extractAnsweredQuestions(questions, refreshedSession?.responses || []);
  const qa = answered
    .filter((item) => item.questionType !== 'knockout')
    .map((item) => ({ question: item.question, transcription: item.transcription }));

  let analysis: CandidateAnalysis;
  if (!control.aiEnabled || control.modelPolicy === 'fallback_only') {
    analysis = fallbackAnalysis(qa.length);
  } else {
    try {
      analysis = await analyzeCandidate(
        String(job?.title || 'Vaga'),
        buildJobContext(job),
        String(job?.company || 'Empresa'),
        qa
      );
    } catch (err) {
      console.error('[flow] analyzeCandidate fallback:', err);
      analysis = fallbackAnalysis(qa.length);
    }
  }

  analysis.competencyScores = computeCompetencyScores(
    answered
      .filter((item) => item.questionType !== 'knockout')
      .map((item) => ({
        requirementId: item.requirementId,
        requirementText: item.requirementText,
        category: item.category,
        weight: item.weight,
      })),
    analysis.questionScores || []
  );

  const knockoutAnswers = answered.filter((item) => item.questionType === 'knockout');
  if (knockoutAnswers.length > 0) {
    analysis.knockout = {
      status: 'pass',
      reason: 'Requisitos eliminatórios respondidos como atendidos.',
      details: knockoutAnswers.map((item) => ({
        requirementId: item.requirementId,
        requirementText: item.requirementText,
        weight: item.weight,
      })),
    };
  }

  await wa.setSummary(encodeSessionAnalysis(analysis), analysis.matchScore, session.id);

  const candidateMsg =
    'Perfeito! Encerramos sua etapa de áudio. O time de RH vai avaliar seu diagnóstico e te atualizar pelos próximos canais.';
  await wa.logMessage(uid(), session.id, 'outbound', 'text', candidateMsg, '', 'sent');
  await sendTextMessage(session.candidate_phone, candidateMsg);

  return {
    nextState: 'completed',
    recruiterSummary: analysis.summary,
  };
}

export async function createSession(
  candidatePhone: string,
  candidateName: string,
  jobId: string,
  jobTitle: string,
  companyName: string,
  recruiterId: string
): Promise<string> {
  const sessionId = uid();
  const job = (await dual.getJobById(jobId)) as any;

  const resolvedJobTitle = String(jobTitle || job?.title || 'Vaga');
  const resolvedCompanyName = String(companyName || job?.company || 'Empresa');
  const questions = await buildSessionQuestionsForJob({
    title: resolvedJobTitle,
    description: job?.description,
    requirements: job?.requirements,
  });

  await wa.createSession(
    sessionId,
    candidatePhone,
    candidateName,
    jobId,
    recruiterId,
    JSON.stringify(questions)
  );

  try {
    await sendTemplate(candidatePhone, TEMPLATES.INVITE.name, 'pt_BR', [
      {
        type: 'body',
        sub_type: 'text',
        parameters: TEMPLATES.INVITE.buildVariables(
          candidateName,
          resolvedJobTitle,
          resolvedCompanyName
        ),
      },
    ] as any);
    await wa.logMessage(
      uid(),
      sessionId,
      'outbound',
      'template',
      `Template: ${TEMPLATES.INVITE.name}`,
      '',
      'sent'
    );
  } catch (err: any) {
    console.error(`[flow] Failed to send invite to ${candidatePhone}:`, err.message);
    await wa.logMessage(
      uid(),
      sessionId,
      'outbound',
      'template',
      `Failed: ${err.message}`,
      '',
      'failed'
    );
  }

  return sessionId;
}

export async function processInboundMessage(
  fromPhone: string,
  messageType: 'text' | 'audio',
  content: string,
  isAudio?: boolean
): Promise<{ sessionId: string; nextState: string; replyMessage?: string }> {
  const session = (await wa.getSessionByPhone(fromPhone)) as any;

  if (!session) {
    await sendTextMessage(
      fromPhone,
      'Olá! No momento não temos um processo ativo para seu número. Entre em contato com o recrutador para mais informações.'
    );
    return { sessionId: '', nextState: 'no_session' };
  }

  const job = (await dual.getJobById(session.job_id)) as any;
  if (!job) {
    await sendTextMessage(
      fromPhone,
      'Não localizei os dados da vaga neste momento. O recrutador será avisado para regularizar o processo.'
    );
    return { sessionId: session.id, nextState: session.state };
  }
  const aiControl = await getAIControl();

  let userMessage = content;
  if (isAudio) {
    const audioRecordId = uid();
    try {
      const audio = await downloadMediaWithMeta(content);
      const totalBytes = Number(audio.fileSize || audio.buffer.byteLength || 0);
      if (totalBytes > aiControl.maxAudioBytes) {
        await sendTextMessage(
          fromPhone,
          'Seu áudio ficou muito longo para análise. Envie uma resposta de até 2 minutos, por favor.'
        );
        return { sessionId: session.id, nextState: session.state };
      }
      await wa.createAudioRecord(audioRecordId, session.id, content, `wa://${content}`);
      userMessage = await transcribeAudio(audio.buffer, audio.mimeType || 'audio/ogg');
      await wa.updateAudioTranscription(userMessage, audioRecordId);
    } catch (err) {
      console.error('[flow] audio processing failed:', err);
      await sendTextMessage(
        fromPhone,
        'Tive um problema para ouvir seu áudio. Pode responder por texto ou reenviar o áudio?'
      );
      return { sessionId: session.id, nextState: session.state };
    }
  }

  await wa.logMessage(uid(), session.id, 'inbound', messageType, userMessage, '', 'delivered');

  if (session.state === 'completed' || session.state === 'declined') {
    const closedMsg =
      'Este processo já foi encerrado. Se houver nova vaga, o RH fará novo convite.';
    await wa.logMessage(uid(), session.id, 'outbound', 'text', closedMsg, '', 'sent');
    await sendTextMessage(fromPhone, closedMsg);
    return { sessionId: session.id, nextState: session.state, replyMessage: closedMsg };
  }

  if (isExplicitDeclineIntent(userMessage)) {
    await wa.declineSession(session.id);
    await wa.logMessage(uid(), session.id, 'outbound', 'text', TEXT_MESSAGES.DECLINED, '', 'sent');
    await sendTextMessage(fromPhone, TEXT_MESSAGES.DECLINED);
    return { sessionId: session.id, nextState: 'declined', replyMessage: TEXT_MESSAGES.DECLINED };
  }

  if (session.state === 'handoff_requested') {
    const waitingMsg =
      'Seu atendimento já foi encaminhado para o recrutador responsável. Em breve você receberá retorno humano por este canal.';
    await wa.logMessage(uid(), session.id, 'outbound', 'text', waitingMsg, '', 'sent');
    await sendTextMessage(fromPhone, waitingMsg);
    return { sessionId: session.id, nextState: 'handoff_requested', replyMessage: waitingMsg };
  }

  if (
    ['accepted', 'questioning', 'consent_pending', 'mic_check'].includes(String(session.state)) &&
    isHumanHandoffIntent(userMessage)
  ) {
    const handoffMsg =
      'Perfeito. Vou encaminhar agora para atendimento humano do RH. Nossa automação fica pausada até o recrutador assumir.';
    await wa.updateSessionState('handoff_requested', session.id);
    await wa.addResponse(
      {
        system: 'handoff_requested',
        reason: sanitizeForModelInput(userMessage),
        requestedAt: new Date().toISOString(),
      },
      session.id,
      { advanceQuestion: false }
    );
    await wa.logMessage(uid(), session.id, 'outbound', 'text', handoffMsg, '', 'sent');
    await sendTextMessage(fromPhone, handoffMsg);
    return { sessionId: session.id, nextState: 'handoff_requested', replyMessage: handoffMsg };
  }

  if (session.state === 'invited') {
    if (!isExplicitAcceptIntent(userMessage)) {
      const guide =
        'Para iniciar sua triagem, responda *SIM*. Se preferir não participar, responda *NÃO*.';
      await wa.logMessage(uid(), session.id, 'outbound', 'text', guide, '', 'sent');
      await sendTextMessage(fromPhone, guide);
      return { sessionId: session.id, nextState: 'invited', replyMessage: guide };
    }

    await wa.updateSessionState('consent_pending', session.id);
    await wa.logMessage(
      uid(),
      session.id,
      'outbound',
      'text',
      TEXT_MESSAGES.CONSENT_REQUEST,
      '',
      'sent'
    );
    await sendTextMessage(fromPhone, TEXT_MESSAGES.CONSENT_REQUEST);
    return {
      sessionId: session.id,
      nextState: 'consent_pending',
      replyMessage: TEXT_MESSAGES.CONSENT_REQUEST,
    };
  }

  if (session.state === 'consent_pending') {
    if (isExplicitDeclineIntent(userMessage)) {
      await wa.declineSession(session.id);
      await wa.logMessage(
        uid(),
        session.id,
        'outbound',
        'text',
        TEXT_MESSAGES.CONSENT_DECLINED,
        '',
        'sent'
      );
      await sendTextMessage(fromPhone, TEXT_MESSAGES.CONSENT_DECLINED);
      return {
        sessionId: session.id,
        nextState: 'declined',
        replyMessage: TEXT_MESSAGES.CONSENT_DECLINED,
      };
    }

    if (!isExplicitAcceptIntent(userMessage)) {
      await wa.logMessage(
        uid(),
        session.id,
        'outbound',
        'text',
        TEXT_MESSAGES.CONSENT_REMINDER,
        '',
        'sent'
      );
      await sendTextMessage(fromPhone, TEXT_MESSAGES.CONSENT_REMINDER);
      return {
        sessionId: session.id,
        nextState: 'consent_pending',
        replyMessage: TEXT_MESSAGES.CONSENT_REMINDER,
      };
    }

    await wa.updateSessionState('mic_check', session.id);
    await wa.logMessage(
      uid(),
      session.id,
      'outbound',
      'text',
      TEXT_MESSAGES.MIC_CHECK_REQUEST,
      '',
      'sent'
    );
    await sendTextMessage(fromPhone, TEXT_MESSAGES.MIC_CHECK_REQUEST);
    return {
      sessionId: session.id,
      nextState: 'mic_check',
      replyMessage: TEXT_MESSAGES.MIC_CHECK_REQUEST,
    };
  }

  if (session.state === 'mic_check') {
    if (!isAudio && !canUseTextFallback(userMessage, aiControl)) {
      await wa.logMessage(
        uid(),
        session.id,
        'outbound',
        'text',
        TEXT_MESSAGES.MIC_CHECK_REMINDER,
        '',
        'sent'
      );
      await sendTextMessage(fromPhone, TEXT_MESSAGES.MIC_CHECK_REMINDER);
      return {
        sessionId: session.id,
        nextState: 'mic_check',
        replyMessage: TEXT_MESSAGES.MIC_CHECK_REMINDER,
      };
    }

    const questions = await ensureSessionQuestions(session, job);
    const firstQuestion =
      questions[0]?.text || 'Conte brevemente sobre sua experiência mais relevante para esta vaga.';
    const kickoff = `${TEXT_MESSAGES.MIC_CHECK_SUCCESS}\n\n${TEXT_MESSAGES.FIRST_QUESTION(String(job.title || 'Vaga'), firstQuestion)}`;

    await wa.addResponse(
      {
        system: 'mic_check_completed',
        answerType: isAudio ? 'audio' : 'text',
        text: sanitizeForModelInput(userMessage),
        createdAt: new Date().toISOString(),
      },
      session.id,
      { advanceQuestion: false }
    );
    await wa.updateSessionState('accepted', session.id);
    await wa.logMessage(uid(), session.id, 'outbound', 'text', kickoff, '', 'sent');
    await sendTextMessage(fromPhone, kickoff);
    return { sessionId: session.id, nextState: 'accepted', replyMessage: kickoff };
  }

  const questions = await ensureSessionQuestions(session, job);
  const questionIdx = Math.max(0, Number(session.current_question_idx || 0));
  const currentQuestion = questions[questionIdx];

  if (session.state === 'accepted') {
    await wa.updateSessionState('questioning', session.id);
  }

  if (!currentQuestion) {
    const completion = await finalizeSession(session, job, questions, aiControl);
    return {
      sessionId: session.id,
      nextState: completion.nextState,
      replyMessage: completion.recruiterSummary,
    };
  }

  if (!isAudio && !canUseTextFallback(userMessage, aiControl)) {
    const audioRequiredMsg =
      'Para esta etapa de triagem, preciso da resposta em *áudio* (até 2 minutos). Se estiver com problema técnico, me avise em texto.';
    await wa.logMessage(uid(), session.id, 'outbound', 'text', audioRequiredMsg, '', 'sent');
    await sendTextMessage(fromPhone, audioRequiredMsg);
    return { sessionId: session.id, nextState: 'questioning', replyMessage: audioRequiredMsg };
  }

  if (looksLikePromptInjection(userMessage)) {
    await wa.addResponse(
      {
        questionIdx,
        system: 'prompt_injection_flag',
        text: sanitizeForModelInput(userMessage),
        createdAt: new Date().toISOString(),
      },
      session.id,
      { advanceQuestion: false }
    );
  }

  const deepDiveAlreadyRequested = hasDeepDiveMarker(session.responses, questionIdx);
  if (currentQuestion.questionType === 'knockout') {
    const knockoutResult = evaluateKnockoutReply(userMessage);
    if (knockoutResult === 'unclear') {
      const clarification =
        'Para seguir, preciso de uma confirmação objetiva deste requisito eliminatório. Responda apenas *SIM* ou *NÃO*.';
      await wa.addResponse(
        {
          questionIdx,
          question: currentQuestion.text,
          questionType: currentQuestion.questionType,
          requirementId: currentQuestion.requirementId,
          requirementText: currentQuestion.requirementText,
          weight: currentQuestion.weight,
          system: 'knockout_unclear',
          text: sanitizeForModelInput(userMessage),
          answeredAt: new Date().toISOString(),
        },
        session.id,
        { advanceQuestion: false }
      );
      await wa.logMessage(uid(), session.id, 'outbound', 'text', clarification, '', 'sent');
      await sendTextMessage(fromPhone, clarification);
      return { sessionId: session.id, nextState: 'questioning', replyMessage: clarification };
    }

    if (knockoutResult === 'fail') {
      const declineReason = `Requisito eliminatório não atendido: ${currentQuestion.requirementText || currentQuestion.text}`;
      const declineAnalysis: CandidateAnalysis = {
        matchScore: 0,
        summary: 'Triagem encerrada por critério eliminatório obrigatório da vaga.',
        strengths: [],
        concerns: [declineReason],
        recommendation: 'rejeitar',
        questionScores: [],
        competencyScores: [],
        knockout: {
          status: 'fail',
          reason: declineReason,
          requirementId: currentQuestion.requirementId,
          requirementText: currentQuestion.requirementText,
          weight: currentQuestion.weight,
          questionType: 'knockout',
          answer: sanitizeForModelInput(userMessage),
        },
      };

      await wa.addResponse(
        {
          questionIdx,
          question: currentQuestion.text,
          questionType: currentQuestion.questionType,
          requirementId: currentQuestion.requirementId,
          requirementText: currentQuestion.requirementText,
          weight: currentQuestion.weight,
          text: sanitizeForModelInput(userMessage),
          type: messageType,
          answeredAt: new Date().toISOString(),
        },
        session.id,
        { advanceQuestion: false }
      );
      await wa.declineSessionWithSummary(session.id, encodeSessionAnalysis(declineAnalysis), 0);

      const declinedMsg =
        'Obrigado pelo retorno. Este requisito é eliminatório para esta vaga, então o processo foi encerrado nesta etapa.';
      await wa.logMessage(uid(), session.id, 'outbound', 'text', declinedMsg, '', 'sent');
      await sendTextMessage(fromPhone, declinedMsg);
      return { sessionId: session.id, nextState: 'declined', replyMessage: declinedMsg };
    }
  }

  if (
    currentQuestion.questionType !== 'knockout' &&
    !deepDiveAlreadyRequested &&
    shouldAskDeepDive(currentQuestion, userMessage, aiControl)
  ) {
    const followup = buildDeepDivePrompt(currentQuestion);
    await wa.addResponse(
      {
        questionIdx,
        question: currentQuestion.text,
        questionType: currentQuestion.questionType,
        requirementId: currentQuestion.requirementId,
        requirementText: currentQuestion.requirementText,
        weight: currentQuestion.weight,
        system: 'deep_dive_requested',
        requestedAt: new Date().toISOString(),
      },
      session.id,
      { advanceQuestion: false }
    );
    await wa.logMessage(uid(), session.id, 'outbound', 'text', followup, '', 'sent');
    await sendTextMessage(fromPhone, followup);
    return { sessionId: session.id, nextState: 'questioning', replyMessage: followup };
  }

  await wa.addResponse(
    {
      questionIdx,
      question: currentQuestion.text,
      questionType: currentQuestion.questionType,
      requirementId: currentQuestion.requirementId,
      requirementText: currentQuestion.requirementText,
      weight: currentQuestion.weight,
      text: sanitizeForModelInput(userMessage),
      type: messageType,
      answeredAt: new Date().toISOString(),
    },
    session.id
  );

  const nextQuestionIdx = questionIdx + 1;
  if (nextQuestionIdx < questions.length) {
    const nextQuestion = TEXT_MESSAGES.NEXT_QUESTION(questions[nextQuestionIdx].text);
    await wa.logMessage(uid(), session.id, 'outbound', 'text', nextQuestion, '', 'sent');
    await sendTextMessage(fromPhone, nextQuestion);
    return { sessionId: session.id, nextState: 'questioning', replyMessage: nextQuestion };
  }

  const completion = await finalizeSession(session, job, questions, aiControl);
  return {
    sessionId: session.id,
    nextState: completion.nextState,
    replyMessage: completion.recruiterSummary,
  };
}

import { isExplicitAcceptIntent, isExplicitDeclineIntent, normalizeUserText } from './intents.js';

export type RequirementImportance = 'must_have' | 'preferred';
export type RequirementEvidenceType = 'objective' | 'behavioral' | 'technical' | 'situational';
export type SessionQuestionType = 'knockout' | 'bars';

export interface StructuredRequirement {
  id: string;
  text: string;
  category: string;
  importance: RequirementImportance;
  weight: number;
  knockout: boolean;
  evidenceType: RequirementEvidenceType;
  knockoutQuestion?: string;
  barsAnchors: Record<1 | 2 | 3 | 4 | 5, string>;
}

export interface StructuredSessionQuestion {
  id: string;
  text: string;
  category: string;
  type: SessionQuestionType;
  requirementId?: string;
  requirementText?: string;
  weight?: number;
  barsAnchors?: Record<1 | 2 | 3 | 4 | 5, string>;
}

export interface CompetencyScore {
  requirementId: string;
  requirementText: string;
  category: string;
  weight: number;
  score: number;
  barsLevel: 1 | 2 | 3 | 4 | 5;
  evidence: 'fraca' | 'moderada' | 'forte';
  rationale: string;
}

function toRequirementId(text: string, idx: number): string {
  const slug = normalizeUserText(text)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48);
  return slug || `req-${idx + 1}`;
}

function clampWeight(value: unknown, fallback: number): number {
  const raw = Number(value);
  if (!Number.isFinite(raw)) return fallback;
  return Math.max(1, Math.min(5, Math.round(raw)));
}

function inferCategory(text: string): string {
  const t = normalizeUserText(text);
  if (/(python|java|react|sql|api|dados|analise|análise|devops|cloud|typescript)/.test(t))
    return 'technical';
  if (/(lideranca|liderança|gestao|gestão|comunicacao|comunicação|conflito|time)/.test(t))
    return 'behavioral';
  if (/(prazo|meta|kpi|resultado|impacto|entrega|projeto)/.test(t)) return 'delivery';
  return 'experience';
}

function inferEvidenceType(category: string): RequirementEvidenceType {
  const c = normalizeUserText(category);
  if (/(technical|tecnico|tecnica)/.test(c)) return 'technical';
  if (/(behavioral|comportamental|soft)/.test(c)) return 'behavioral';
  if (/(situational|situacional|cenario|cenario)/.test(c)) return 'situational';
  return 'objective';
}

function normalizeImportance(rawImportance: unknown, rawType: unknown): RequirementImportance {
  const value = normalizeUserText(String(rawImportance ?? rawType ?? ''));
  if (/(must_have|must|mandatory|obrigatorio|obrigatória|obrigatorio)/.test(value))
    return 'must_have';
  return 'preferred';
}

function normalizeEvidenceType(
  rawEvidenceType: unknown,
  category: string
): RequirementEvidenceType {
  const value = normalizeUserText(String(rawEvidenceType || ''));
  if (/(technical|tecnico|tecnica|portfolio|portifolio|case)/.test(value)) return 'technical';
  if (/(behavioral|comportamental|experience|experiencia|audio_answer)/.test(value))
    return 'behavioral';
  if (/(situational|situacional|scenario|cenario)/.test(value)) return 'situational';
  if (/(objective|objetivo)/.test(value)) return 'objective';
  return inferEvidenceType(category);
}

function defaultBarsAnchors(
  evidenceType: RequirementEvidenceType
): Record<1 | 2 | 3 | 4 | 5, string> {
  if (evidenceType === 'technical') {
    return {
      1: 'Sem evidência técnica prática.',
      2: 'Conhecimento básico sem aplicação clara.',
      3: 'Aplicação técnica em contexto limitado.',
      4: 'Aplicação consistente com bons resultados.',
      5: 'Domínio técnico com impacto comprovado e replicável.',
    };
  }
  if (evidenceType === 'behavioral') {
    return {
      1: 'Sem exemplo comportamental observável.',
      2: 'Exemplo vago e sem ação clara.',
      3: 'Exemplo adequado com ação parcial.',
      4: 'Exemplo claro com ação e resultado consistente.',
      5: 'Exemplo robusto com liderança e impacto mensurável.',
    };
  }
  if (evidenceType === 'situational') {
    return {
      1: 'Não apresenta abordagem para o cenário.',
      2: 'Abordagem fraca e sem priorização.',
      3: 'Abordagem razoável com lacunas.',
      4: 'Boa abordagem com critérios e execução.',
      5: 'Abordagem excelente, estruturada e orientada a impacto.',
    };
  }
  return {
    1: 'Sem evidência suficiente.',
    2: 'Evidência fraca e genérica.',
    3: 'Evidência moderada.',
    4: 'Evidência forte e consistente.',
    5: 'Evidência excelente com resultados claros.',
  };
}

export function normalizeJobRequirements(input: unknown): StructuredRequirement[] {
  if (!Array.isArray(input)) return [];

  return input
    .map((raw: any, idx): StructuredRequirement | null => {
      const text = typeof raw === 'string' ? raw.trim() : String(raw?.text || '').trim();
      if (!text) return null;

      const normalizedImportance = normalizeImportance(raw?.importance, raw?.type);
      const category = String(raw?.category || inferCategory(text)).trim() || 'experience';
      const evidenceType = normalizeEvidenceType(raw?.evidenceType, category);
      const fallbackWeight = normalizedImportance === 'must_have' ? 4 : 2;
      const weight = clampWeight(raw?.weight, fallbackWeight);
      const knockout = Boolean(raw?.knockout);

      const customAnchors =
        raw?.barsAnchors && typeof raw.barsAnchors === 'object' ? raw.barsAnchors : null;
      const defaults = defaultBarsAnchors(evidenceType);
      const barsAnchors: Record<1 | 2 | 3 | 4 | 5, string> = {
        1: String(customAnchors?.[1] || defaults[1]),
        2: String(customAnchors?.[2] || defaults[2]),
        3: String(customAnchors?.[3] || defaults[3]),
        4: String(customAnchors?.[4] || defaults[4]),
        5: String(customAnchors?.[5] || defaults[5]),
      };

      return {
        id: toRequirementId(text, idx),
        text,
        category,
        importance: normalizedImportance,
        weight,
        knockout,
        evidenceType,
        knockoutQuestion:
          typeof raw?.knockoutQuestion === 'string' ? raw.knockoutQuestion.trim() : undefined,
        barsAnchors,
      };
    })
    .filter((req): req is StructuredRequirement => !!req);
}

function buildKnockoutQuestion(jobTitle: string, req: StructuredRequirement): string {
  if (req.knockoutQuestion) return req.knockoutQuestion;
  return `Requisito eliminatório para a vaga de ${jobTitle}: ${req.text}. Você atende esse requisito hoje? Responda apenas SIM ou NÃO.`;
}

function buildBarsQuestion(req: StructuredRequirement): string {
  const evidenceHint =
    req.evidenceType === 'technical'
      ? 'Explique stack, decisão técnica e impacto.'
      : req.evidenceType === 'behavioral'
        ? 'Detalhe contexto, sua ação e resultado com pessoas/time.'
        : req.evidenceType === 'situational'
          ? 'Descreva sua decisão em um cenário prático e trade-offs.'
          : 'Use o formato Situação -> Ação -> Resultado.';

  return `Sobre "${req.text}", descreva um caso real da sua experiência. ${evidenceHint}`;
}

export function buildStructuredQuestions(
  jobTitle: string,
  requirements: StructuredRequirement[],
  options?: { maxKnockoutQuestions?: number; maxBarsQuestions?: number }
): StructuredSessionQuestion[] {
  const maxKnockout = Math.max(0, Math.min(options?.maxKnockoutQuestions ?? 5, 8));
  const maxBars = Math.max(1, Math.min(options?.maxBarsQuestions ?? 4, 8));

  const knockouts = requirements
    .filter((r) => r.knockout)
    .sort((a, b) => b.weight - a.weight)
    .slice(0, maxKnockout)
    .map((r) => ({
      id: `ko_${r.id}`,
      text: buildKnockoutQuestion(jobTitle, r),
      category: r.category,
      type: 'knockout' as const,
      requirementId: r.id,
      requirementText: r.text,
      weight: r.weight,
    }));

  const bars = requirements
    .filter((r) => !r.knockout)
    .sort((a, b) => {
      if (a.importance === b.importance) return b.weight - a.weight;
      return a.importance === 'must_have' ? -1 : 1;
    })
    .slice(0, maxBars)
    .map((r) => ({
      id: `bars_${r.id}`,
      text: buildBarsQuestion(r),
      category: r.category,
      type: 'bars' as const,
      requirementId: r.id,
      requirementText: r.text,
      weight: r.weight,
      barsAnchors: r.barsAnchors,
    }));

  return [...knockouts, ...bars];
}

export function evaluateKnockoutReply(answer: string): 'pass' | 'fail' | 'unclear' {
  if (isExplicitAcceptIntent(answer)) return 'pass';
  if (isExplicitDeclineIntent(answer)) return 'fail';
  const t = normalizeUserText(answer);
  if (/^(sim|yes|ok|confirmo|atendo)\b/.test(t)) return 'pass';
  if (/^(nao|não|no|negativo|nao atendo|não atendo)\b/.test(t)) return 'fail';
  return 'unclear';
}

export function barsLevelFromScore(rawScore: number): 1 | 2 | 3 | 4 | 5 {
  const score = Math.max(0, Math.min(100, Math.round(rawScore)));
  if (score < 20) return 1;
  if (score < 40) return 2;
  if (score < 60) return 3;
  if (score < 80) return 4;
  return 5;
}

export function computeCompetencyScores(
  rows: Array<{
    requirementId?: string;
    requirementText?: string;
    category?: string;
    weight?: number;
  }>,
  questionScores: number[]
): CompetencyScore[] {
  return rows
    .map((row, idx) => {
      if (!row.requirementId || !row.requirementText) return null;
      const score = Math.max(0, Math.min(100, Math.round(Number(questionScores[idx] ?? 50))));
      const barsLevel = barsLevelFromScore(score);
      const evidence: 'fraca' | 'moderada' | 'forte' =
        barsLevel <= 2 ? 'fraca' : barsLevel === 3 ? 'moderada' : 'forte';
      const rationale =
        evidence === 'forte'
          ? 'Evidência robusta com ação e resultado observável.'
          : evidence === 'moderada'
            ? 'Evidência parcial; há clareza, mas faltam métricas ou profundidade.'
            : 'Evidência fraca ou genérica; exige validação adicional.';

      return {
        requirementId: row.requirementId,
        requirementText: row.requirementText,
        category: String(row.category || 'experience'),
        weight: Math.max(1, Math.min(5, Math.round(Number(row.weight || 1)))),
        score,
        barsLevel,
        evidence,
        rationale,
      };
    })
    .filter((v): v is CompetencyScore => !!v);
}

