function paginate<T>(items: T[], limit: number, offset: number) {
  const safeLimit = Math.min(Math.max(limit, 1), 100);
  const safeOffset = Math.max(offset, 0);
  return {
    data: items.slice(safeOffset, safeOffset + safeLimit),
    total: items.length,
    limit: safeLimit,
    offset: safeOffset,
  };
}

function shapeSessionForApi(session: any) {
  const rawSummary = typeof session?.summary === 'string' ? session.summary : null;
  const parsed = decodeSessionAnalysis(session?.summary);
  let rawParsedSummary: any = null;

  if (rawSummary) {
    try {
      rawParsedSummary = JSON.parse(rawSummary);
    } catch {
      rawParsedSummary = null;
    }
  }

  const toNumber = (value: unknown, fallback: number) => {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  };

  const normalizeQuestionScores = (value: unknown): number[] => {
    if (!Array.isArray(value)) return [];
    return value
      .map((v) => Math.round(toNumber(v, NaN)))
      .filter((v) => Number.isFinite(v))
      .map((v) => Math.max(0, Math.min(100, v)));
  };

  const normalizeStringArray = (value: unknown): string[] => {
    if (!Array.isArray(value)) return [];
    return value.filter((v): v is string => typeof v === 'string' && v.trim().length > 0);
  };

  const normalizeCompetencyScores = (
    value: unknown
  ): Array<{
    requirement_id: string;
    requirement_text: string;
    category: string;
    weight: number;
    score: number;
    bars_level: 1 | 2 | 3 | 4 | 5;
    evidence: 'fraca' | 'moderada' | 'forte';
    rationale: string;
  }> => {
    if (!Array.isArray(value)) return [];
    return value
      .map((item) => {
        if (!item || typeof item !== 'object') return null;
        const row = item as Record<string, unknown>;
        const requirementId = String(row.requirement_id ?? row.requirementId ?? '').trim();
        const requirementText = String(row.requirement_text ?? row.requirementText ?? '').trim();
        if (!requirementId || !requirementText) return null;

        const barsRaw = Math.round(
          toNumber(
            row.bars_level ?? row.barsLevel,
            Math.ceil(Math.max(0, Math.min(100, toNumber(row.score, 0))) / 20)
          )
        );
        const barsLevel = Math.max(1, Math.min(5, barsRaw)) as 1 | 2 | 3 | 4 | 5;
        const evidenceRaw = String(row.evidence || '').trim();
        const evidence =
          evidenceRaw === 'fraca' || evidenceRaw === 'moderada' || evidenceRaw === 'forte'
            ? evidenceRaw
            : barsLevel <= 2
              ? 'fraca'
              : barsLevel === 3
                ? 'moderada'
                : 'forte';

        return {
          requirement_id: requirementId,
          requirement_text: requirementText,
          category: String(row.category || 'experience'),
          weight: Math.max(1, Math.min(5, Math.round(toNumber(row.weight, 1)))),
          score: Math.max(0, Math.min(100, Math.round(toNumber(row.score, 0)))),
          bars_level: barsLevel,
          evidence,
          rationale: String(row.rationale || ''),
        };
      })
      .filter(
        (
          row
        ): row is {
          requirement_id: string;
          requirement_text: string;
          category: string;
          weight: number;
          score: number;
          bars_level: 1 | 2 | 3 | 4 | 5;
          evidence: 'fraca' | 'moderada' | 'forte';
          rationale: string;
        } => !!row
      );
  };

  const normalizeKnockout = (
    value: unknown
  ): {
    failed: boolean;
    reason: string;
    requirement_id: string | null;
    requirement_text: string | null;
    answer: string | null;
  } | null => {
    if (!value || typeof value !== 'object') return null;
    const row = value as Record<string, unknown>;
    const status = row.status === 'pass' || row.status === 'fail' ? row.status : null;
    const failed = status ? status === 'fail' : Boolean(row.failed);
    const reason = String(row.reason || '').trim();
    if (!failed && !reason) return null;
    return {
      failed,
      reason,
      requirement_id: row.requirement_id
        ? String(row.requirement_id)
        : row.requirementId
          ? String(row.requirementId)
          : null,
      requirement_text: row.requirement_text
        ? String(row.requirement_text)
        : row.requirementText
          ? String(row.requirementText)
          : null,
      answer: row.answer ? String(row.answer) : null,
    };
  };

  const summary =
    parsed.summary ??
    (rawParsedSummary && typeof rawParsedSummary.summary === 'string'
      ? rawParsedSummary.summary
      : null);
  const strengths =
    parsed.strengths.length > 0
      ? parsed.strengths
      : normalizeStringArray(rawParsedSummary?.strengths);
  const concerns =
    parsed.concerns.length > 0 ? parsed.concerns : normalizeStringArray(rawParsedSummary?.concerns);
  const recommendation =
    parsed.recommendation ||
    (rawParsedSummary?.recommendation === 'entrevista' ||
    rawParsedSummary?.recommendation === 'rejeitar' ||
    rawParsedSummary?.recommendation === 'mais_info'
      ? rawParsedSummary.recommendation
      : null);
  const questionScores =
    parsed.questionScores.length > 0
      ? parsed.questionScores
      : normalizeQuestionScores(
          rawParsedSummary?.questionScores ?? rawParsedSummary?.question_scores
        );
  const competencyScores = normalizeCompetencyScores(
    session?.competency_scores ??
      rawParsedSummary?.competencyScores ??
      rawParsedSummary?.competency_scores
  );
  const knockout = normalizeKnockout(session?.knockout ?? rawParsedSummary?.knockout);

  return {
    ...session,
    summary,
    strengths,
    concerns,
    recommendation,
    question_scores: questionScores,
    competency_scores: competencyScores,
    knockout,
  };
}

type NormalizedRequirement = {
  text: string;
  category: string;
  importance: 'must_have' | 'preferred';
  weight: number;
  knockout: boolean;
  evidenceType: 'objective' | 'behavioral' | 'technical' | 'situational';
  knockoutQuestion?: string;
};

function normalizeJobRequirementsPayload(input: unknown): NormalizedRequirement[] {
  if (!Array.isArray(input)) return [];

  const normalizeImportance = (raw: unknown): 'must_have' | 'preferred' => {
    const value = String(raw || '')
      .trim()
      .toLowerCase();
    return value === 'must_have' ||
      value === 'must' ||
      value === 'mandatory' ||
      value === 'obrigatorio'
      ? 'must_have'
      : 'preferred';
  };

  const normalizeEvidenceType = (
    raw: unknown,
    category: string
  ): 'objective' | 'behavioral' | 'technical' | 'situational' => {
    const value = String(raw || '')
      .trim()
      .toLowerCase();
    if (['technical', 'tecnico', 'portfolio', 'case'].includes(value)) return 'technical';
    if (['behavioral', 'comportamental', 'experience', 'audio_answer'].includes(value))
      return 'behavioral';
    if (['situational', 'situacional', 'scenario', 'cenario'].includes(value)) return 'situational';
    if (['objective', 'objetivo'].includes(value)) return 'objective';

    const normalizedCategory = category.trim().toLowerCase();
    if (normalizedCategory.includes('tech')) return 'technical';
    if (normalizedCategory.includes('comport')) return 'behavioral';
    if (normalizedCategory.includes('situac')) return 'situational';
    return 'objective';
  };

  return input
    .map((row): NormalizedRequirement | null => {
      const isObject = !!row && typeof row === 'object';
      const rawText =
        typeof row === 'string' ? row : isObject ? (row as Record<string, unknown>).text : '';
      const text = String(rawText || '').trim();
      if (!text) return null;

      const raw = (isObject ? row : {}) as Record<string, unknown>;
      const category = String(raw.category || 'skill').trim() || 'skill';
      const weightRaw = Math.round(Number(raw.weight ?? 3));
      const weight = Number.isFinite(weightRaw) ? Math.max(1, Math.min(5, weightRaw)) : 3;
      const knockoutQuestion = String(raw.knockoutQuestion || '').trim();

      return {
        text,
        category,
        importance: normalizeImportance(raw.importance),
        weight,
        knockout: Boolean(raw.knockout),
        evidenceType: normalizeEvidenceType(raw.evidenceType, category),
        knockoutQuestion: knockoutQuestion || undefined,
      };
    })
    .filter((v): v is NormalizedRequirement => !!v);
}

function fail(
  res: express.Response,
  status: number,
  error: string,
  code?: string,
  details?: unknown
) {
  const correlationId = (res.locals?.correlationId as string | undefined) || null;
  const payload: { error: string; code?: string; details?: unknown } = { error };
  if (code) payload.code = code;
  if (details !== undefined || correlationId) {
    if (details && typeof details === 'object' && !Array.isArray(details)) {
      payload.details = { ...(details as Record<string, unknown>), correlationId };
    } else if (details !== undefined) {
      payload.details = { value: details, correlationId };
    } else {
      payload.details = { correlationId };
    }
  }
  return res.status(status).json(payload);
}

function logEvent(
  level: 'info' | 'warn' | 'error',
  event: string,
  fields: Record<string, unknown> = {}
) {
  const line = JSON.stringify({
    ts: new Date().toISOString(),
    level,
    service: SERVICE,
    event,
    ...fields,
  });
  if (level === 'error') console.error(line);
  else if (level === 'warn') console.warn(line);
  else console.log(line);
}

function mustHave(name: string) {
  if (!process.env[name]) {
