/**
 * WhatsApp Webhook Handler
 * Receives events from Meta's WhatsApp Cloud API webhook.
 *
 * Setup:
 * 1. In Meta App Dashboard → WhatsApp → Configuration → Webhook
 * 2. Set callback URL to: https://your-domain.com/api/whatsapp/webhook
 * 3. Set Verify Token (any secret string)
 * 4. Subscribe to messages
 */

import type { Request, Response } from 'express';
import crypto from 'crypto';
import { processInboundMessage } from '../conversation/flow.js';
import { wa } from '../storage/db.js';

const VERIFY_TOKEN = process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN || 'recruta-ai-verify';
const APP_SECRET = process.env.WHATSAPP_APP_SECRET || '';

function isValidSignature(req: Request): boolean {
  if (!APP_SECRET) return process.env.NODE_ENV !== 'production';

  const signature = req.headers['x-hub-signature-256'];
  if (typeof signature !== 'string' || !signature.startsWith('sha256=')) return false;

  const rawBody = (req as any).rawBody || JSON.stringify(req.body || {});
  const expected = `sha256=${crypto.createHmac('sha256', APP_SECRET).update(rawBody).digest('hex')}`;
  if (signature.length !== expected.length) return false;
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}

/**
 * GET — Webhook verification (challenge from Meta)
 */
export function handleVerification(req: Request, res: Response) {
  const mode = req.query['hub.mode'];
  const token = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];

  if (mode === 'subscribe' && token === VERIFY_TOKEN) {
    console.log('[webhook] Verified successfully');
    res.status(200).send(String(challenge));
  } else {
    res.sendStatus(403);
  }
}

/**
 * POST — Webhook events (incoming messages, delivery receipts, etc.)
 */
export async function handleEvent(req: Request, res: Response) {
  if (!isValidSignature(req)) {
    return res
      .status(401)
      .json({ error: 'Invalid webhook signature', code: 'WEBHOOK_INVALID_SIGNATURE' });
  }

  let body: any = {};
  try {
    body = typeof req.body === 'string' ? JSON.parse(req.body || '{}') : req.body;
  } catch {
    return res.status(400).json({ error: 'Invalid JSON payload', code: 'WEBHOOK_INVALID_JSON' });
  }

  // Acknowledge receipt immediately (Meta requires < 5s response)
  res.sendStatus(200);

  try {
    // WhatsApp sends messages in an object.Entry array
    const entries = body.entry;
    if (!entries || entries.length === 0) return;

    for (const entry of entries) {
      const changes = entry.changes || [];
      for (const change of changes) {
        const messages = change.value?.messages || [];
        const statuses = change.value?.statuses || [];

        // Handle incoming messages
        for (const msg of messages) {
          if (msg.type === 'unsupported') continue; // Ignore unsupported types

          const from = msg.from; // Phone number (e.g., "5549999999999")
          const msgType = msg.type; // "text" | "audio" | "image" | etc.

          if (msgType === 'text' && msg.text) {
            await processInboundMessage(from, 'text', msg.text.body);
          } else if (msgType === 'audio' && msg.audio) {
            const mediaId = msg.audio.id;
            await processInboundMessage(from, 'audio', mediaId, true);
          }
        }

        // Handle status updates (delivered, read, failed)
        for (const status of statuses) {
          if (status.id) {
            await wa.logMessage(
              `status_${status.id}`,
              null as any,
              'outbound',
              'text',
              `Status: ${status.status}`,
              status.id,
              status.status
            );
          }
        }
      }
    }
  } catch (err: any) {
    console.error('[webhook] Error processing event:', err);
  }
}

import React, { useState } from 'react';
import { Loader2, Mic, RotateCcw, Square, Wand2 } from 'lucide-react';
import { useAudioRecorder } from '../hooks/useAudioRecorder';

interface AudioInputProps {
  maxDurationSec?: number;
  onTranscribe?: (audio: Blob) => Promise<void>;
  className?: string;
}

function formatDuration(sec: number): string {
  const mins = Math.floor(sec / 60)
    .toString()
    .padStart(2, '0');
  const secs = (sec % 60).toString().padStart(2, '0');
  return `${mins}:${secs}`;
}

const AudioInput: React.FC<AudioInputProps> = ({
  maxDurationSec = 120,
  onTranscribe,
  className,
}) => {
  const { isSupported, isRecording, audioBlob, audioUrl, durationSec, error, start, stop, reset } =
    useAudioRecorder({ maxDurationSec });
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [transcribeError, setTranscribeError] = useState<string | null>(null);

  const canTranscribe = !!audioBlob && !!onTranscribe && !isTranscribing;

  async function handleTranscribe() {
    if (!audioBlob || !onTranscribe) return;
    setIsTranscribing(true);
    setTranscribeError(null);
    try {
      await onTranscribe(audioBlob);
    } catch (err: any) {
      setTranscribeError(err?.message || 'Falha ao transcrever áudio.');
    } finally {
      setIsTranscribing(false);
    }
  }

  return (
    <div
      className={`rounded-xl border border-slate-200 dark:border-slate-700 p-4 bg-slate-50 dark:bg-slate-800/40 ${className || ''}`}
    >
      <div className="flex flex-wrap items-center gap-2">
        {!isRecording ? (
          <button
            type="button"
            onClick={start}
            disabled={!isSupported}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-purple-600 text-white text-sm font-bold disabled:opacity-50"
          >
            <Mic size={16} /> Gravar áudio
          </button>
        ) : (
          <button
            type="button"
            onClick={stop}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-red-600 text-white text-sm font-bold"
          >
            <Square size={14} /> Parar
          </button>
        )}

        <button
          type="button"
          onClick={reset}
          disabled={!audioBlob && !isRecording}
          className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 text-sm font-medium disabled:opacity-50"
        >
          <RotateCcw size={14} /> Limpar
        </button>

        {onTranscribe && (
          <button
            type="button"
            onClick={handleTranscribe}
            disabled={!canTranscribe}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-emerald-600 text-white text-sm font-bold disabled:opacity-50"
          >
            {isTranscribing ? <Loader2 size={14} className="animate-spin" /> : <Wand2 size={14} />}
            {isTranscribing ? 'Transcrevendo...' : 'Transcrever áudio'}
          </button>
        )}

        <span className="ml-auto text-xs font-semibold text-slate-500">
          {isRecording
            ? `Gravando ${formatDuration(durationSec)} / ${formatDuration(maxDurationSec)}`
            : 'Até 2 minutos'}
        </span>
      </div>

      {audioUrl && (
        <div className="mt-3">
          <audio controls src={audioUrl} className="w-full" />
        </div>
      )}

      {!isSupported && (
        <p className="mt-3 text-xs text-amber-700 dark:text-amber-400">
          Seu navegador não suporta gravação nativa de áudio.
        </p>
      )}

      {(error || transcribeError) && (
        <p className="mt-3 text-xs text-red-600 dark:text-red-400">{error || transcribeError}</p>
      )}
    </div>
  );
};

