import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import {
  ApiError,
  getCurrentUser,
  login as loginRequest,
  register as registerRequest,
} from '../services/api';

export type UserRole = 'candidate' | 'recruiter' | 'admin';

export interface User {
  id: string;
  role: UserRole;
  email: string;
  name?: string;
}

export interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (
    email: string,
    password: string,
    role: Exclude<UserRole, 'admin'>,
    name?: string
  ) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const stored = localStorage.getItem('recruta_user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  });
  const [isLoading, setIsLoading] = useState(false);

  // Restore & validate session on mount
  useEffect(() => {
    const token = localStorage.getItem('recruta_token');
    if (!token) return;
    getCurrentUser()
      .then((data: any) => {
        const u: User = { id: data.id, role: data.role, email: data.email, name: data.name };
        setUser(u);
        localStorage.setItem('recruta_user', JSON.stringify(u));
      })
      .catch(() => {
        setUser(null);
        localStorage.removeItem('recruta_token');
        localStorage.removeItem('recruta_user');
      });
  }, []);

  const login = async (email: string, password: string) => {
    setIsLoading(true);
    try {
      const data = await loginRequest(email, password);
      localStorage.setItem('recruta_token', data.token);
      const u: User = { id: data.userId, role: data.role, email: data.email, name: data.name };
      setUser(u);
      localStorage.setItem('recruta_user', JSON.stringify(u));
    } catch (error) {
      if (error instanceof ApiError) {
        throw new Error(error.message);
      }
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (
    email: string,
    password: string,
    role: Exclude<UserRole, 'admin'>,
    name?: string
  ) => {
    setIsLoading(true);
    try {
      const data = await registerRequest(email, password, role, name);
      localStorage.setItem('recruta_token', data.token);
      const u: User = {
        id: data.userId,
        role: data.role,
        email: data.email,
        name: data.name || name,
      };
      setUser(u);
      localStorage.setItem('recruta_user', JSON.stringify(u));
    } catch (error) {
      if (error instanceof ApiError) {
        throw new Error(error.message);
      }
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('recruta_token');
    localStorage.removeItem('recruta_user');
  };

  return (
    <AuthContext.Provider
      value={{ user, isAuthenticated: !!user, isLoading, login, register, logout }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

import { useCallback, useState } from 'react';

export function useAsyncState<T>(initialData: T) {
  const [data, setData] = useState<T>(initialData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const run = useCallback(async <R>(fn: () => Promise<R>, onSuccess?: (result: R) => void) => {
    setLoading(true);
    setError(null);
    try {
      const result = await fn();
      onSuccess?.(result);
      return result;
    } catch (err: any) {
      setError(err?.message || 'Erro inesperado');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  return { data, setData, loading, error, setError, run };
}

import { useCallback, useEffect, useRef, useState } from 'react';

interface UseAudioRecorderOptions {
  maxDurationSec?: number;
  preferredMimeType?: string;
}

export function useAudioRecorder(options: UseAudioRecorderOptions = {}) {
  const { maxDurationSec = 120, preferredMimeType = 'audio/webm;codecs=opus' } = options;

  const [isSupported] = useState(
    typeof window !== 'undefined' &&
      typeof navigator !== 'undefined' &&
      !!navigator.mediaDevices?.getUserMedia &&
      typeof MediaRecorder !== 'undefined'
  );
  const [isRecording, setIsRecording] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [durationSec, setDurationSec] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const streamRef = useRef<MediaStream | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);
  const timerRef = useRef<number | null>(null);
  const tickRef = useRef<number | null>(null);

  const cleanupStream = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
  }, []);

  const clearTimers = useCallback(() => {
    if (timerRef.current) {
      window.clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    if (tickRef.current) {
      window.clearInterval(tickRef.current);
      tickRef.current = null;
    }
  }, []);

  const reset = useCallback(() => {
    clearTimers();
    cleanupStream();
    mediaRecorderRef.current = null;
    chunksRef.current = [];
    setIsRecording(false);
    setDurationSec(0);
    setError(null);
    setAudioBlob(null);
    if (audioUrl) {
      URL.revokeObjectURL(audioUrl);
      setAudioUrl(null);
    }
  }, [audioUrl, cleanupStream, clearTimers]);

  const stop = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
    }
  }, []);

  const start = useCallback(async () => {
    if (!isSupported) {
      setError('Gravação de áudio não suportada neste navegador.');
      return;
    }

    try {
      setError(null);
      chunksRef.current = [];
      setAudioBlob(null);
      if (audioUrl) {
        URL.revokeObjectURL(audioUrl);
        setAudioUrl(null);
      }
      setDurationSec(0);

      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      streamRef.current = stream;

      const mimeType = MediaRecorder.isTypeSupported(preferredMimeType)
        ? preferredMimeType
        : 'audio/webm';

      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) chunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        clearTimers();
        cleanupStream();

        const blob = new Blob(chunksRef.current, { type: mimeType });
        chunksRef.current = [];
        if (!blob.size) {
          setError('Não foi possível capturar o áudio. Tente novamente.');
          setIsRecording(false);
          return;
        }

        const url = URL.createObjectURL(blob);
        setAudioBlob(blob);
        setAudioUrl(url);
        setIsRecording(false);
      };

      mediaRecorder.start();
      setIsRecording(true);

      tickRef.current = window.setInterval(() => {
        setDurationSec((prev) => prev + 1);
      }, 1000);

      timerRef.current = window.setTimeout(() => {
        stop();
      }, maxDurationSec * 1000);
    } catch (err: any) {
      cleanupStream();
      setIsRecording(false);
      setError(err?.message || 'Não foi possível acessar o microfone.');
    }
  }, [audioUrl, cleanupStream, clearTimers, isSupported, maxDurationSec, preferredMimeType, stop]);

  useEffect(() => {
    return () => {
      clearTimers();
      cleanupStream();
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl, cleanupStream, clearTimers]);

  return {
    isSupported,
    isRecording,
    audioBlob,
    audioUrl,
    durationSec,
    error,
    start,
    stop,
    reset,
  };
}

import { useCallback, useEffect, useState } from 'react';
import {
  analyzeCV,
  applyToJob,
  createDiagnosticPayment,
  getCandidateProfile,
  getPublicJobs,
} from '../services/api';
import type { CVAnalysisResult, CandidateProfile, PaymentCustomer, PublicJob } from '../contracts/api';

export function useCandidateDashboard() {
  const [profile, setProfile] = useState<CandidateProfile | null>(null);
  const [jobs, setJobs] = useState<PublicJob[]>([]);
  const [analysis, setAnalysis] = useState<CVAnalysisResult | null>(null);
  const [appliedJobs, setAppliedJobs] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [profileRes, jobsRes] = await Promise.all([getCandidateProfile(), getPublicJobs()]);
      setProfile(profileRes);
      setJobs(jobsRes.data);
      if (profileRes?.scp_score > 0) {
        setAnalysis({
          score: profileRes.scp_score,
          reasoning: profileRes.diagnosis,
          suggestions: profileRes.attention_points || [],
          fallback: true,
        });
      }
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Erro ao carregar painel do candidato');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const runAnalyzeCV = useCallback(
    async (cvText: string) => {
      const result = await analyzeCV(cvText);
      setAnalysis(result.data || result.fallback);
      await refresh();
      return result;
    },
    [refresh]
  );

  const runApply = useCallback(async (jobId: string) => {
    await applyToJob({ jobId });
    setAppliedJobs((prev) => new Set(prev).add(jobId));
  }, []);

  const runDiagnosticCheckout = useCallback(async (customer?: PaymentCustomer) => {
    return createDiagnosticPayment(customer);
  }, []);

  return {
    profile,
    jobs,
    analysis,
    appliedJobs,
    loading,
    error,
    refresh,
    runAnalyzeCV,
    runApply,
    runDiagnosticCheckout,
  };
}

import { useCallback, useMemo, useState } from 'react';

interface SpeakOptions {
  lang?: string;
  rate?: number;
  pitch?: number;
  volume?: number;
}

export function useTextToSpeech(defaultLang = 'pt-BR') {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isSupported = useMemo(
    () => typeof window !== 'undefined' && typeof window.speechSynthesis !== 'undefined',
    []
  );

  const stop = useCallback(() => {
    if (!isSupported) return;
    window.speechSynthesis.cancel();
    setIsSpeaking(false);
  }, [isSupported]);

  const speak = useCallback(
    (text: string, options: SpeakOptions = {}) => {
      if (!isSupported) {
        setError('Text-to-speech não suportado neste navegador.');
        return;
      }
      if (!text.trim()) return;

      try {
        setError(null);
        stop();

        const utter = new SpeechSynthesisUtterance(text.trim());
        utter.lang = options.lang || defaultLang;
        utter.rate = options.rate ?? 1;
        utter.pitch = options.pitch ?? 1;
        utter.volume = options.volume ?? 1;

        utter.onstart = () => setIsSpeaking(true);
        utter.onend = () => setIsSpeaking(false);
        utter.onerror = () => {
          setIsSpeaking(false);
          setError('Falha ao reproduzir áudio sintetizado.');
        };

        window.speechSynthesis.speak(utter);
      } catch (err: any) {
        setIsSpeaking(false);
        setError(err?.message || 'Falha ao iniciar text-to-speech.');
      }
    },
    [defaultLang, isSupported, stop]
  );

  return {
    isSupported,
    isSpeaking,
    error,
    speak,
    stop,
  };
}

import { useCallback, useEffect, useState } from 'react';
import { getRecruiterWhatsAppSessions, getWhatsAppSessions } from '../services/api';
import type { WhatsAppSession } from '../contracts/api';

export function useWhatsAppSessions(jobId?: string) {
  const [sessions, setSessions] = useState<WhatsAppSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = jobId
        ? await getWhatsAppSessions(jobId)
        : await getRecruiterWhatsAppSessions();
      setSessions(response.data);
    } catch (err: any) {
      setError(err?.message || 'Erro ao carregar sessões de WhatsApp');
      setSessions([]);
    } finally {
      setLoading(false);
    }
  }, [jobId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { sessions, loading, error, refresh };
}

