import React, { useEffect, useMemo, useState } from 'react';
import { Clock, CheckCircle, XCircle, FileText, PlayCircle, Loader2, Volume2 } from 'lucide-react';
import { getAudioBlob, getRecruiterSessions, getSessionAudios } from '../services/whatsappApi';
import { useTextToSpeech } from '../hooks/useTextToSpeech';
import type { WhatsAppSession, WhatsAppAudioFile } from '../contracts/api';

type ReviewRow = {
  session: WhatsAppSession;
  audios: WhatsAppAudioFile[];
};

const PendingReviews = () => {
  const [rows, setRows] = useState<ReviewRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);

  const { speak, stop, isSpeaking } = useTextToSpeech('pt-BR');

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const sessions = await getRecruiterSessions();
      const active = sessions.filter((s) => ['questioning', 'completed'].includes(s.state));

      const withAudios = await Promise.all(
        active.map(async (session) => {
          const audios = await getSessionAudios(session.id);
          return { session, audios };
        })
      );

      setRows(withAudios.filter((entry) => entry.audios.length > 0));
    } catch (err: any) {
      setRows([]);
      setError(err?.message || 'Erro ao carregar revisões pendentes.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  const pendingCandidates = useMemo(
    () =>
      rows.map((entry) => {
        const latestAudio = entry.audios[entry.audios.length - 1];
        return {
          id: entry.session.id,
          session: entry.session,
          latestAudio,
          totalAudios: entry.audios.length,
          transcription: latestAudio?.transcription || null,
          status: entry.session.state === 'completed' ? 'completed' : 'processing',
        };
      }),
    [rows]
  );

  async function handlePlay(audioId: string) {
    try {
      setPlayingAudioId(audioId);
      const blob = await getAudioBlob(audioId);
      const url = URL.createObjectURL(blob);
      const player = new Audio(url);
      player.onended = () => {
        URL.revokeObjectURL(url);
        setPlayingAudioId(null);
      };
      player.onerror = () => {
        URL.revokeObjectURL(url);
        setPlayingAudioId(null);
      };
      await player.play();
    } catch {
      setPlayingAudioId(null);
      setError('Não foi possível reproduzir o áudio.');
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Revisão Pendente</h1>
          <p className="text-slate-500 text-sm">
            Candidatos com áudio em triagem para revisão do recrutador.
          </p>
        </div>
        <button
          type="button"
          onClick={load}
          className="px-3 py-2 rounded-lg border border-slate-300 text-sm font-medium hover:bg-slate-50"
        >
          Atualizar
        </button>
      </div>

      {error && (
        <div className="p-3 rounded-xl border border-red-200 bg-red-50 text-sm text-red-700">
          {error}
        </div>
      )}

      <div className="grid gap-4">
        {loading && (
          <div className="text-center py-8 text-slate-500 text-sm">
            <Loader2 size={18} className="animate-spin mx-auto mb-2" />
            Carregando revisões...
          </div>
        )}

        {!loading &&
          pendingCandidates.map((candidate) => (
            <div
              key={candidate.id}
              className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6"
            >
              <div className="flex-1">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center font-bold">
                      {(candidate.session.candidate_name || 'CA').substring(0, 2).toUpperCase()}
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-900">
                        {candidate.session.candidate_name || 'Candidato'}
                      </h3>
                      <p className="text-xs text-slate-500">
                        Iniciado em{' '}
                        {new Date(candidate.session.created_at).toLocaleDateString('pt-BR')} •{' '}
                        {candidate.session.candidate_phone}
                      </p>
                    </div>
                  </div>
                  <div
                    className={`px-3 py-1 rounded-full text-xs font-bold uppercase ${
                      candidate.status === 'processing'
                        ? 'bg-blue-100 text-blue-700'
                        : 'bg-emerald-100 text-emerald-700'
                    }`}
                  >
                    {candidate.status === 'processing' ? 'Em Análise' : 'Concluído'}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm mb-4">
                  <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                    <span className="block text-xs text-slate-400 mb-1">Motivo da Pendência</span>
                    <span className="font-medium text-slate-700">
                      {candidate.transcription
                        ? 'Áudio recebido e transcrito. Revisão manual recomendada.'
                        : 'Áudio recebido sem transcrição. Reprocessar.'}
                    </span>
                  </div>
                  <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                    <span className="block text-xs text-slate-400 mb-1">Áudios recebidos</span>
                    <span className="font-medium text-slate-700">{candidate.totalAudios}</span>
                  </div>
                </div>

                {candidate.transcription && (
                  <div className="mb-4 p-3 rounded-lg border border-slate-200 bg-slate-50">
                    <p className="text-xs text-slate-400 mb-1">Última transcrição</p>
                    <p className="text-sm text-slate-700 line-clamp-3">{candidate.transcription}</p>
                  </div>
                )}

                <div className="flex flex-wrap gap-3">
                  <button
                    type="button"
                    onClick={() => handlePlay(candidate.latestAudio.id)}
                    disabled={playingAudioId === candidate.latestAudio.id}
                    className="flex items-center gap-2 text-sm text-blue-600 hover:text-blue-800 font-medium disabled:opacity-50"
                  >
                    {playingAudioId === candidate.latestAudio.id ? (
                      <Loader2 size={16} className="animate-spin" />
                    ) : (
                      <PlayCircle size={16} />
                    )}
                    Ouvir Áudio Original
                  </button>

                  {candidate.transcription && (
                    <button
                      type="button"
                      onClick={() => (isSpeaking ? stop() : speak(candidate.transcription || ''))}
                      className="flex items-center gap-2 text-sm text-purple-600 hover:text-purple-800 font-medium"
                    >
                      <Volume2 size={16} /> {isSpeaking ? 'Parar leitura' : 'Ouvir transcrição'}
                    </button>
                  )}

                  <button className="flex items-center gap-2 text-sm text-slate-500 hover:text-slate-700 font-medium">
                    <FileText size={16} /> Ver Log do Sistema
                  </button>
                </div>
              </div>

              <div className="md:w-64 flex flex-col justify-center gap-3 md:border-l md:border-slate-100 md:pl-6">
                <button className="w-full py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium text-sm flex items-center justify-center gap-2 transition-colors">
                  <CheckCircle size={16} /> Aprovar Manualmente
                </button>
                <button className="w-full py-2 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded-lg font-medium text-sm flex items-center justify-center gap-2 transition-colors">
                  <Clock size={16} /> Reprocessar
                </button>
                <button className="w-full py-2 bg-white border border-red-200 hover:bg-red-50 text-red-600 rounded-lg font-medium text-sm flex items-center justify-center gap-2 transition-colors">
                  <XCircle size={16} /> Rejeitar / Cancelar
                </button>
              </div>
            </div>
          ))}

        {!loading && pendingCandidates.length === 0 && (
          <div className="text-center py-12 bg-slate-50 rounded-xl border border-dashed border-slate-300">
            <CheckCircle className="mx-auto text-green-500 mb-3" size={32} />
            <h3 className="text-lg font-medium text-slate-900">Tudo limpo!</h3>
            <p className="text-slate-500">Não há revisões com áudio pendentes no momento.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PendingReviews;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Mic, Loader2, Mail, Lock, User, Eye, EyeOff, CheckCircle2 } from 'lucide-react';

const RegisterPage: React.FC = () => {
  const { register, isLoading } = useAuth();
  const navigate = useNavigate();

  const [role, setRole] = useState<'candidate' | 'recruiter'>('candidate');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');

  const passwordStrength = (() => {
    if (password.length === 0) return 0;
    let score = 0;
    if (password.length >= 8) score++;
    if (/[A-Z]/.test(password)) score++;
    if (/[0-9]/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;
    return score;
  })();

  const strengthLabel = ['', 'Fraca', 'Regular', 'Boa', 'Forte'][passwordStrength];
  const strengthColor = ['', 'bg-red-500', 'bg-amber-500', 'bg-blue-500', 'bg-emerald-500'][
    passwordStrength
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!name.trim()) {
      setError('Digite seu nome.');
      return;
    }
    if (!email.trim() || !email.includes('@')) {
      setError('Digite um e-mail válido.');
      return;
    }
    if (password.length < 8) {
      setError('Senha deve ter no mínimo 8 caracteres.');
      return;
    }
    if (password !== confirmPassword) {
      setError('As senhas não coincidem.');
      return;
    }

    try {
      await register(email.trim().toLowerCase(), password, role, name.trim());
      navigate(role === 'candidate' ? '/candidate' : '/recruiter', { replace: true });
    } catch (err: any) {
      setError(err.message || 'Erro ao criar conta. Tente novamente.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 mb-4 shadow-xl">
            <Mic size={24} />
          </div>
          <h1 className="text-2xl font-extrabold text-slate-900 dark:text-white tracking-tight">
            Recruta<span className="text-purple-600">.AI</span>
          </h1>
          <p className="text-sm text-slate-500 mt-1">Crie sua conta gratuita</p>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm">
          {/* Role selector */}
          <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl mb-6">
            {(['candidate', 'recruiter'] as const).map((r) => (
              <button
                key={r}
                type="button"
                onClick={() => setRole(r)}
                className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${
                  role === r
                    ? 'bg-white dark:bg-purple-600 text-purple-700 dark:text-white shadow-sm'
                    : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                }`}
              >
                {r === 'candidate' ? '🧑 Candidato' : '🏢 Recrutador'}
              </button>
            ))}
          </div>

          {/* Role description */}
          <div
            className={`p-3 rounded-xl mb-5 text-xs ${
              role === 'candidate'
                ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-700 dark:text-purple-300'
                : 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300'
            }`}
          >
            {role === 'candidate'
              ? '📄 Analise seu currículo com IA, candidate-se a vagas e receba feedback de triagens.'
              : '🎯 Publique vagas, analise currículos em massa e trieie candidatos via WhatsApp.'}
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Name */}
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                Nome completo
              </label>
              <div className="relative">
                <User
                  size={16}
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
                <input
                  id="register-name"
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Seu nome"
                  autoComplete="name"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                />
              </div>
            </div>

            {/* Email */}
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                E-mail
              </label>
              <div className="relative">
                <Mail
                  size={16}
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
                <input
                  id="register-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="voce@email.com"
                  autoComplete="email"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                />
              </div>
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                Senha
              </label>
              <div className="relative">
                <Lock
                  size={16}
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
                <input
                  id="register-password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Mínimo 8 caracteres"
                  autoComplete="new-password"
                  className="w-full pl-10 pr-10 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword((v) => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                >
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
              {/* Password strength bar */}
              {password.length > 0 && (
                <div className="mt-2 flex items-center gap-2">
                  <div className="flex-1 flex gap-1">
                    {[1, 2, 3, 4].map((i) => (
                      <div
                        key={i}
                        className={`h-1 flex-1 rounded-full transition-colors ${
                          i <= passwordStrength ? strengthColor : 'bg-slate-200 dark:bg-slate-700'
                        }`}
                      />
                    ))}
                  </div>
                  <span className="text-xs text-slate-500">{strengthLabel}</span>
                </div>
              )}
            </div>

            {/* Confirm Password */}
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                Confirmar senha
              </label>
              <div className="relative">
                <Lock
                  size={16}
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
                <input
                  id="register-confirm-password"
                  type={showPassword ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="Repita a senha"
                  autoComplete="new-password"
                  className="w-full pl-10 pr-10 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                />
                {confirmPassword && (
                  <div className="absolute right-3 top-1/2 -translate-y-1/2">
                    {password === confirmPassword ? (
                      <CheckCircle2 size={16} className="text-emerald-500" />
                    ) : (
                      <span className="text-red-400 text-xs">✗</span>
                    )}
                  </div>
                )}
              </div>
            </div>

            {error && (
              <div className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl px-4 py-3">
                {error}
              </div>
            )}

            <button
              id="register-submit"
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-slate-900 dark:bg-purple-600 text-white rounded-xl font-bold text-sm hover:opacity-90 transition-opacity disabled:opacity-50 flex items-center justify-center gap-2 shadow-lg"
            >
              {isLoading ? (
                <>
                  <Loader2 size={18} className="animate-spin" /> Criando conta...
                </>
              ) : (
                'Criar conta'
              )}
            </button>

            <p className="text-xs text-slate-400 text-center">
              Ao criar conta, você concorda com os{' '}
              <Link to="/termos" className="text-purple-600 hover:underline">
                Termos de Uso
              </Link>{' '}
              e{' '}
              <Link to="/privacidade" className="text-purple-600 hover:underline">
                Política de Privacidade
              </Link>
              .
            </p>
          </form>
        </div>

        <p className="text-center text-sm text-slate-500 mt-6">
          Já tem conta?{' '}
          <Link
            to="/login"
            className="text-purple-600 dark:text-purple-400 font-bold hover:underline"
          >
            Entrar
          </Link>
        </p>
      </div>
    </div>
  );
};

export default RegisterPage;

import React, { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, BarChart3, Bot, RefreshCcw, Save, ShieldCheck, Users } from 'lucide-react';
import type { AdminAIControlSettings, AdminOverview } from '../../contracts/api';
import { getAdminOverview, updateAdminAIControl } from '../../services/api';

const money = (cents: number) =>
  new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format((cents || 0) / 100);

const AdminDashboard: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [overview, setOverview] = useState<AdminOverview | null>(null);
  const [control, setControl] = useState<AdminAIControlSettings | null>(null);

  const load = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getAdminOverview();
      setOverview(data);
      setControl(data.aiControl);
    } catch (err: any) {
      setError(err?.message || 'Falha ao carregar painel admin.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const userRoleRows = useMemo(() => Object.entries(overview?.users.byRole || {}), [overview]);
  const sessionStateRows = useMemo(
    () => Object.entries(overview?.triage.byState || {}),
    [overview]
  );

  const saveControl = async () => {
    if (!control) return;
    setSaving(true);
    setError('');
    try {
      const updated = await updateAdminAIControl(control);
      setControl(updated);
      await load();
    } catch (err: any) {
      setError(err?.message || 'Falha ao salvar controle de IA.');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="py-16 text-center text-slate-500 dark:text-slate-300">
        Carregando console admin...
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-900 dark:text-white">
            Painel Gestor (Admin)
          </h1>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            Operação global + governança de IA. Atualizado em{' '}
            {overview?.generatedAt ? new Date(overview.generatedAt).toLocaleString('pt-BR') : '—'}
          </p>
        </div>
        <button
          onClick={load}
          className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 text-sm font-semibold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800"
        >
          <RefreshCcw size={14} /> Atualizar
        </button>
      </div>

      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4">
          <p className="text-xs uppercase tracking-wider text-slate-500">Usuários</p>
          <p className="mt-1 text-3xl font-black">{overview?.users.total || 0}</p>
        </div>
        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4">
          <p className="text-xs uppercase tracking-wider text-slate-500">Vagas ativas</p>
          <p className="mt-1 text-3xl font-black">{overview?.jobs.active || 0}</p>
        </div>
        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4">
          <p className="text-xs uppercase tracking-wider text-slate-500">
            Taxa de conclusão da triagem
          </p>
          <p className="mt-1 text-3xl font-black">{overview?.triage.completionRate ?? 0}%</p>
        </div>
        <div className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4">
          <p className="text-xs uppercase tracking-wider text-slate-500">Receita paga</p>
          <p className="mt-1 text-3xl font-black">
            {money(overview?.revenue.paidRevenueCents || 0)}
          </p>
        </div>
      </div>

      <div className="grid xl:grid-cols-3 gap-4">
        <div className="xl:col-span-2 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-4">
          <div className="flex items-center gap-2 mb-3">
            <BarChart3 size={16} className="text-slate-500" />
            <h2 className="font-bold">Analytics Global</h2>
          </div>
          <div className="grid md:grid-cols-2 gap-4 text-sm">
            <div>
              <p className="font-semibold mb-2 flex items-center gap-2">
                <Users size={14} /> Usuários por role
              </p>
              <ul className="space-y-1">
                {userRoleRows.map(([role, count]) => (
                  <li
                    key={role}
                    className="flex justify-between border-b border-slate-100 dark:border-slate-800 py-1"
