import React, { useState, useEffect } from 'react';
import { getRecruiterWallet, getPublicJobs, getJobApplications } from '../../services/api';
import type { CreditTransaction, JobApplication, PublicJob, RecruiterWallet } from '../../contracts/api';
import {
  DollarSign,
  Users,
  Zap,
  Award,
  ArrowUpRight,
  BarChart3,
  Activity,
  Target,
  Clock,
} from 'lucide-react';

const RecruiterAnalytics = () => {
  const [loading, setLoading] = useState(true);
  const [wallet, setWallet] = useState<RecruiterWallet | null>(null);
  const [transactions, setTransactions] = useState<CreditTransaction[]>([]);
  const [jobs, setJobs] = useState<PublicJob[]>([]);
  const [jobApps, setJobApps] = useState<Record<string, JobApplication[]>>({});

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [walletData, jobsResult] = await Promise.all([
        getRecruiterWallet().catch(() => ({ wallet: null, transactions: [], payments: [] })),
        getPublicJobs().catch(() => ({ data: [], total: 0 })),
      ]);
      setWallet(walletData.wallet);
      setTransactions(walletData.transactions || []);
      const jobList = jobsResult.data;
      setJobs(jobList);

      // Load applications per job
      const apps: Record<string, JobApplication[]> = {};
      for (const job of jobList) {
        try {
          const result = await getJobApplications(job.id);
          apps[job.id] = result.data;
        } catch {
          apps[job.id] = [];
        }
      }
      setJobApps(apps);
    } catch {
      /* no data */
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="animate-spin w-8 h-8 border-4 border-slate-300 border-t-emerald-500 rounded-full" />
      </div>
    );
  }

  const totalApplications = Object.values(jobApps).reduce((sum, a) => sum + a.length, 0);
  const avgMatchScore =
    totalApplications > 0
      ? Math.round(
          Object.values(jobApps)
            .flat()
            .reduce((sum, a) => sum + (a.match_score || 0), 0) / totalApplications
        )
      : 0;
  const topJob = jobs.reduce(
    (best, j) => {
      const count = jobApps[j.id]?.length || 0;
      return count > (best.count || 0) ? { job: j, count } : best;
    },
    { job: null, count: 0 } as { job: PublicJob | null; count: number }
  );

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-16 animate-fade-in">
      <div>
        <h1 className="text-2xl font-black text-slate-900 dark:text-white">Analytics</h1>
        <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">
          Métricas de desempenho do seu recrutamento
        </p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
              Vagas Ativas
            </span>
            <div className="p-2 bg-blue-50 dark:bg-blue-500/10 rounded-lg">
              <BriefcaseIcon size={18} className="text-blue-600" />
            </div>
          </div>
          <p className="text-3xl font-black text-slate-900 dark:text-white">{jobs.length}</p>
          <div className="flex items-center gap-1 mt-2 text-xs text-emerald-600 dark:text-emerald-400 font-bold">
            <ArrowUpRight size={12} />
            {jobs.filter((j) => j.is_active).length} publicadas
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
              Candidaturas
            </span>
            <div className="p-2 bg-purple-50 dark:bg-purple-500/10 rounded-lg">
              <Users size={18} className="text-purple-600" />
            </div>
          </div>
          <p className="text-3xl font-black text-slate-900 dark:text-white">{totalApplications}</p>
          <div className="flex items-center gap-1 mt-2 text-xs text-slate-500 font-bold">
            <Target size={12} />
            Média {avgMatchScore}% match
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
              Créditos
            </span>
            <div className="p-2 bg-emerald-50 dark:bg-emerald-500/10 rounded-lg">
              <DollarSign size={18} className="text-emerald-600" />
            </div>
          </div>
          <p className="text-3xl font-black text-slate-900 dark:text-white">
            {wallet?.balance || 0}
          </p>
          <div className="flex items-center gap-1 mt-2 text-xs text-slate-500 font-bold">
            <Zap size={12} />
            {wallet?.total_spent || 0} utilizados
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
              Top Vaga
            </span>
            <div className="p-2 bg-amber-50 dark:bg-amber-500/10 rounded-lg">
              <Award size={18} className="text-amber-600" />
            </div>
          </div>
          <p className="text-lg font-black text-slate-900 dark:text-white truncate">
            {topJob.job?.title || '—'}
          </p>
          <div className="flex items-center gap-1 mt-2 text-xs text-slate-500 font-bold">
            <Users size={12} />
            {topJob.count} candidatura{topJob.count !== 1 ? 's' : ''}
          </div>
        </div>
      </div>

      {/* Charts area */}
      <div className="grid lg:grid-cols-2 gap-6">
        {/* Applications per Job */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm">
          <div className="flex items-center gap-2 mb-4">
            <BarChart3 size={18} className="text-slate-400" />
            <h3 className="font-bold text-slate-900 dark:text-white">Candidaturas por Vaga</h3>
          </div>
          {jobs.length === 0 ? (
            <p className="text-sm text-slate-500 text-center py-8">Nenhuma vaga ainda.</p>
          ) : (
            <div className="space-y-3">
              {jobs.map((job) => {
                const count = jobApps[job.id]?.length || 0;
                const maxCount = Math.max(...Object.values(jobApps).map((a) => a.length), 1);
                const pct = Math.round((count / maxCount) * 100);
                return (
                  <div key={job.id}>
                    <div className="flex justify-between text-xs mb-1">
                      <span className="font-bold text-slate-700 dark:text-slate-300 truncate mr-2">
                        {job.title}
                      </span>
                      <span className="text-slate-500 shrink-0">{count}</span>
                    </div>
                    <div className="h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                      <div
                        className="h-full bg-emerald-500 rounded-full transition-all"
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Match Score Distribution */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm">
          <div className="flex items-center gap-2 mb-4">
            <Activity size={18} className="text-slate-400" />
            <h3 className="font-bold text-slate-900 dark:text-white">
              Distribuição de Match Score
            </h3>
          </div>
          {totalApplications === 0 ? (
            <p className="text-sm text-slate-500 text-center py-8">Nenhuma candidatura ainda.</p>
          ) : (
            <div className="space-y-3">
              {(() => {
                const allApps = Object.values(jobApps).flat();
                const ranges = [
                  { label: '90-100%', min: 90, max: 100, color: 'bg-emerald-500' },
                  { label: '70-89%', min: 70, max: 89, color: 'bg-blue-500' },
                  { label: '50-69%', min: 50, max: 69, color: 'bg-amber-500' },
                  { label: '0-49%', min: 0, max: 49, color: 'bg-red-500' },
                ];
                return ranges.map((r) => {
                  const count = allApps.filter(
                    (a) => (a.match_score || 0) >= r.min && (a.match_score || 0) <= r.max
                  ).length;
                  const pct =
                    totalApplications > 0 ? Math.round((count / totalApplications) * 100) : 0;
                  return (
                    <div key={r.label}>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="font-bold text-slate-700 dark:text-slate-300">
                          {r.label}
                        </span>
                        <span className="text-slate-500">
                          {count} ({pct}%)
                        </span>
                      </div>
                      <div className="h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                        <div
                          className={`h-full ${r.color} rounded-full transition-all`}
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
          )}
        </div>
      </div>

      {/* Recent Transactions */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm">
        <div className="flex items-center gap-2 mb-4">
          <Clock size={18} className="text-slate-400" />
          <h3 className="font-bold text-slate-900 dark:text-white">Transações Recentes</h3>
        </div>
        {transactions.length === 0 ? (
          <p className="text-sm text-slate-500 text-center py-8">Nenhuma transação ainda.</p>
        ) : (
          <div className="space-y-2">
            {transactions.slice(0, 10).map((tx) => (
              <div
                key={tx.id}
                className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50"
              >
                <div className="flex items-center gap-3">
                  <div
                    className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                      tx.type === 'purchase'
                        ? 'bg-emerald-100 dark:bg-emerald-900/30'
                        : 'bg-red-100 dark:bg-red-900/30'
                    }`}
                  >
                    {tx.type === 'purchase' ? (
                      <ArrowUpRight size={14} className="text-emerald-600" />
                    ) : (
                      <DollarSign size={14} className="text-red-600" />
                    )}
                  </div>
                  <div>
                    <p className="text-sm font-bold text-slate-900 dark:text-white">
                      {tx.description}
                    </p>
                    <p className="text-[10px] text-slate-400">
                      {new Date(tx.created_at).toLocaleDateString('pt-BR')}
                    </p>
                  </div>
                </div>
                <p
                  className={`text-sm font-black ${tx.type === 'purchase' ? 'text-emerald-600' : 'text-red-600'}`}
                >
                  {tx.type === 'purchase' ? '+' : '-'}
                  {tx.amount} CR
                </p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

